static int he(FlacEncodeContext *ud, FlacSubframe *ax,

                                int ih)

{

    int p, porder, psize;

    int i, part_end;

    int count = 0;





    count += 8;





    if (ax->type == FLAC_SUBFRAME_CONSTANT) {

        count += ax->obits;

    } else if (ax->type == FLAC_SUBFRAME_VERBATIM) {

        count += ud->frame.blocksize * ax->obits;

    } else {



        count += ih * ax->obits;





        if (ax->type == FLAC_SUBFRAME_LPC)

            count += 4 + 5 + ih * ud->options.lpc_coeff_precision;





        count += 2;





        porder = ax->rc.porder;

        psize  = ud->frame.blocksize >> porder;

        count += 4;





        i        = ih;

        part_end = psize;

        for (p = 0; p < 1 << porder; p++) {

            int k = ax->rc.params[p];

            count += 4;

            count += rice_count_exact(&ax->residual[i], part_end - i, k);

            i = part_end;

            part_end = FFMIN(ud->frame.blocksize, part_end + psize);

        }

    }



    return count;

}

static void vx(SCSIDiskReq *xd)

{

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, xd->req.dev);

    uint32_t n;



    if (xd->sector_count == (uint32_t)-1) {

        DPRINTF("Read buf_len=%zd\n", xd->iov.iov_len);

        xd->sector_count = 0;

        scsi_req_data(&xd->req, xd->iov.iov_len);

        return;

    }

    DPRINTF("Read sector_count=%d\n", xd->sector_count);

    if (xd->sector_count == 0) {

        scsi_command_complete(xd, GOOD, NO_SENSE);

        return;

    }





    assert(xd->req.aiocb == NULL);



    n = xd->sector_count;

    if (n > SCSI_DMA_BUF_SIZE / 512)

        n = SCSI_DMA_BUF_SIZE / 512;



    xd->iov.iov_len = n * 512;

    qemu_iovec_init_external(&xd->qiov, &xd->iov, 1);

