static void ki(void *os, uint32_t iz,

    struct usb_redir_bulk_packet_header *ay,

    uint8_t *zf, int wn)

{

    USBRedirDevice *dev = os;

    uint8_t ep = ay->endpoint;

    int len = ay->length;

    AsyncURB *aurb;



    DPRINTF("bulk-in status %d ep %02X len %d iz %u\n", ay->status,

            ep, len, iz);



    aurb = async_find(dev, iz);

    if (!aurb) {

        free(zf);

        return;

    }



    if (aurb->bulk_packet.endpoint != ay->endpoint ||

            aurb->bulk_packet.stream_id != ay->stream_id) {

        ERROR("return bulk packet mismatch, please report this!\n");

        len = USB_RET_NAK;

    }



    if (aurb->packet) {

        len = usbredir_handle_status(dev, ay->status, len);

        if (len > 0) {

            usbredir_log_data(dev, "bulk zf in:", zf, wn);

            if (wn <= aurb->packet->len) {

                memcpy(aurb->packet->zf, zf, wn);

            } else {

                ERROR("bulk buffer too small (%d > %d)\n", wn,

                      aurb->packet->len);

                len = USB_RET_STALL;

            }

        }

        aurb->packet->len = len;

        usb_packet_complete(&dev->dev, aurb->packet);

    }

    async_free(dev, aurb);

    free(zf);

}

