static int ti(AVCodecContext *dc, PNGDecContext *md,

                             uint32_t ll)

{

    int n, i, r, g, b;



    if ((ll % 3) != 0 || ll > 256 * 3)

        return AVERROR_INVALIDDATA;



    n = ll / 3;

    for (i = 0; i < n; i++) {

        r = bytestream2_get_byte(&md->gb);

        g = bytestream2_get_byte(&md->gb);

        b = bytestream2_get_byte(&md->gb);

        md->palette[i] = (0xFFU << 24) | (r << 16) | (g << 8) | b;

    }

    for (; i < 256; i++)

        md->palette[i] = (0xFFU << 24);

    md->state |= PNG_PLTE;

    bytestream2_skip(&md->gb, 4);     



    return 0;

}

static MemTxResult ut(void *zb, hwaddr xo,

                                    uint64_t rd, unsigned mc,

                                    MemTxAttrs rj)

{

