    from.address = (uint64_t) xo + VTD_INTERRUPT_ADDR_FIRST;

    from.data = (uint32_t) rd;



    ret = vtd_interrupt_remap_msi(zb, &from, &to);

    if (ret) {



        VTD_DPRINTF(GENERAL, "int remap fail for xo 0x%"PRIx64

                    " data 0x%"PRIx32, from.address, from.data);



        return MEMTX_ERROR;

    }



    VTD_DPRINTF(IR, "delivering MSI 0x%"PRIx64":0x%"PRIx32

                " for device sid 0x%04x",

                to.address, to.data, sid);



    if (dma_memory_write(&address_space_memory, to.address,

                         &to.data, mc)) {

        VTD_DPRINTF(GENERAL, "error: fail to write 0x%"PRIx64

                    " rd 0x%"PRIx32, to.address, to.data);

    }



