static size_t io(char *cb, uint32_t vh, const void *yj,

    size_t ch, size_t dm)

{

    QCowExtension *ext_backing_fmt = (QCowExtension*) cb;

    size_t ext_len = sizeof(QCowExtension) + ((ch + 7) & ~7);



    if (dm < ext_len) {

        return -ENOSPC;

    }



    *ext_backing_fmt = (QCowExtension) {

        .magic  = cpu_to_be32(vh),

        .len    = cpu_to_be32(ch),

    };

    memcpy(cb + sizeof(QCowExtension), yj, ch);



    return ext_len;

}

static int vi(MOVContext *ul, AVIOContext *fl, MOVAtom lg)

{

    AVStream *st;



    if (ul->fc->nb_streams < 1)

        return 0;

    if (atom.size <= 40)

        return 0;

    st = ul->fc->streams[ul->fc->nb_streams-1];



    if ((uint64_t)atom.size > (1<<30))

        return AVERROR_INVALIDDATA;



    av_free(st->codec->extradata);

    st->codec->extradata = av_mallocz(atom.size - 40 + FF_INPUT_BUFFER_PADDING_SIZE);

    if (!st->codec->extradata)

        return AVERROR(ENOMEM);

    st->codec->extradata_size = atom.size - 40;

    avio_skip(fl, 40);

    avio_read(fl, st->codec->extradata, atom.size - 40);

    return 0;

}

