int attribute_align_arg ic(AVCodecContext *yy, AVFrame *bh,
                                              int *bz,
                                              AVPacket *km)
{
    int ret;
    *bz = 0;
    if ((yy->coded_width || yy->coded_height) && av_image_check_size(yy->coded_width, yy->coded_height, 0, yy))
        return -1;
    yy->pkt = km;
    apply_param_change(yy, km);
    if ((yy->codec->capabilities & CODEC_CAP_DELAY) || km->size || (yy->active_thread_type & FF_THREAD_FRAME)) {
        if (HAVE_THREADS && yy->active_thread_type & FF_THREAD_FRAME)
            ret = ff_thread_decode_frame(yy, bh, bz,
                                         km);
        else {
            ret = yy->codec->decode(yy, bh, bz,
                                       km);
            bh->pkt_dts             = km->dts;
            bh->sample_aspect_ratio = yy->sample_aspect_ratio;
            bh->width               = yy->width;
            bh->height              = yy->height;
            bh->format              = yy->pix_fmt;
        }
        emms_c(); 
        if (*bz)
            yy->frame_number++;
    } else
        ret = 0;

    bh->extended_data = bh->data;
    return ret;
}

