static int ra(AVCodecContext *mm, const AVFrame *to, opj_image_t *qi)

{

    int compno;

    int x, y;

    int *image_line;

    int frame_index;

    const int numcomps  = qi->numcomps;

    uint16_t *frame_ptr = (uint16_t *)to->data[0];



    for (compno = 0; compno < numcomps; ++compno) {

        if (qi->comps[compno].w > to->linesize[0] / numcomps) {

            av_log(mm, AV_LOG_ERROR, "Error: frame's linesize is too small for the image\n");

            return 0;

        }

    }



    for (compno = 0; compno < numcomps; ++compno) {

        for (y = 0; y < mm->height; ++y) {

            image_line = qi->comps[compno].data + y * qi->comps[compno].w;

            frame_index = y * (to->linesize[0] / 2) + compno;

            for (x = 0; x < mm->width; ++x) {

                image_line[x] = frame_ptr[frame_index] >> 4;

                frame_index += numcomps;

            }

            for (; x < qi->comps[compno].w; ++x) {

                image_line[x] = image_line[x - 1];

            }

        }

        for (; y < qi->comps[compno].h; ++y) {

            image_line = qi->comps[compno].data + y * qi->comps[compno].w;

            for (x = 0; x < qi->comps[compno].w; ++x) {

                image_line[x] = image_line[x - qi->comps[compno].w];

            }

        }

    }



    return 1;

}

