static int iq(AVCodecContext *dj, unsigned char *nf, int oa, void *xx){

    FFV1Context *f = dj->priv_data;

    CABACContext * const c= &f->c;

    AVFrame *pict = xx;

    const int width= f->width;

    const int height= f->height;

    AVFrame * const p= &f->picture;

    int used_count= 0;



    if(dj->strict_std_compliance >= 0){

        av_log(dj, AV_LOG_ERROR, "this codec is under development, files encoded with it wont be decodeable with future versions!!!\n"

               "use vstrict=-1 to use it anyway\n");

        return -1;

    }



    ff_init_cabac_encoder(c, nf, oa);

    ff_init_cabac_states(c, ff_h264_lps_range, ff_h264_mps_state, ff_h264_lps_state, 64);

    c->lps_state[2] = 1;

    c->lps_state[3] = 0;



    *p = *pict;

    p->pict_type= FF_I_TYPE;



    if(dj->gop_size==0 || f->picture_number % dj->gop_size == 0){

        put_cabac_bypass(c, 1);

        p->key_frame= 1;

        write_header(f);

        clear_state(f);

    }else{

        put_cabac_bypass(c, 0);

        p->key_frame= 0;

    }



    if(!f->ac){

        used_count += put_cabac_terminate(c, 1);



        init_put_bits(&f->pb, nf + used_count, oa - used_count);

    }



    if(f->colorspace==0){

        const int chroma_width = -((-width )>>f->chroma_h_shift);

        const int chroma_height= -((-height)>>f->chroma_v_shift);



        encode_plane(f, p->xx[0], width, height, p->linesize[0], 0);



        encode_plane(f, p->xx[1], chroma_width, chroma_height, p->linesize[1], 1);

        encode_plane(f, p->xx[2], chroma_width, chroma_height, p->linesize[2], 1);

    }else{

        encode_rgb_frame(f, (uint32_t*)(p->xx[0]), width, height, p->linesize[0]/4);

    }

    emms_c();



    f->picture_number++;



    if(f->ac){

        return put_cabac_terminate(c, 1);

    }else{

        flush_put_bits(&f->pb); 

        return used_count + (put_bits_count(&f->pb)+7)/8;

    }

}

void do_POWER_maskg (yf)

{

    uint32_t ret;



    if ((uint32_t)T0 == (uint32_t)(T1 + 1)) {

        ret = -1;

    } else {

        ret = (((uint32_t)(-1)) >> ((uint32_t)T0)) ^

            (((uint32_t)(-1) >> ((uint32_t)T1)) >> 1);

        if ((uint32_t)T0 > (uint32_t)T1)

            ret = ~ret;

    }

    T0 = ret;

}

static void yf(void *uj, int uq,

                              uint64_t tg, size_t el)

{

    QEDAIOCB *acb = uj;

    BDRVQEDState *s = acb_to_s(acb);

    BlockDriverState *bs = acb->common.bs;





    tg += qed_offset_into_cluster(s, acb->cur_pos);



    trace_yf(s, acb, uq, tg, el);



    if (uq < 0) {

        goto err;

    }



    qemu_iovec_concat(&acb->cur_qiov, acb->qiov, acb->qiov_offset, el);





    if (uq == QED_CLUSTER_ZERO) {

        qemu_iovec_memset(&acb->cur_qiov, 0, 0, acb->cur_qiov.size);

        qed_aio_next_io(acb, 0);

        return;

    } else if (uq != QED_CLUSTER_FOUND) {

        qed_read_backing_file(s, acb->cur_pos, &acb->cur_qiov,

                              qed_aio_next_io, acb);

        return;

    }



    BLKDBG_EVENT(bs->file, BLKDBG_READ_AIO);

    bdrv_aio_readv(bs->file, tg / BDRV_SECTOR_SIZE,

                   &acb->cur_qiov, acb->cur_qiov.size / BDRV_SECTOR_SIZE,

                   qed_aio_next_io, acb);

    return;



err:

    qed_aio_complete(acb, uq);

}

