    sa = ((int64_t)*vp < 0);

    if (sa)

        neg128(ee, vp);

    sb = (rf < 0);

    if (sb)

        rf = -rf;

    div64(ee, vp, rf);

    if (sa ^ sb)

        *ee = - *ee;

    if (sa)

        *vp = - *vp;

}

