    if (st->numComponents == -1) return -1;



    numSubbands = decodeSpectrum (sh, st->spectrum);





    lastTonal = addTonalComponents (st->spectrum, st->numComponents, st->components);







    numBands = (subbandTab[numSubbands] - 1) >> 8;

    if (lastTonal >= 0)

        numBands = FFMAX((lastTonal + 256) >> 8, numBands);







    for (band=0; band<4; band++) {



        if (band <= numBands) {

            IMLT(&(st->spectrum[band*256]), st->IMDCT_buf, band&1);

        } else

            memset(st->IMDCT_buf, 0, 512 * sizeof(float));





        gainCompensateAndOverlap (st->IMDCT_buf, &(st->prevFrame[band*256]), &(bt[band*256]),

                                    &((st->gainBlock[1 - (st->gcBlkSwitch)]).gBlock[band]),

                                    &((st->gainBlock[st->gcBlkSwitch]).gBlock[band]));

    }





    st->gcBlkSwitch ^= 1;



    return 0;

}

