static int ui(AVCodecContext *un, void *ib, int *ak,

                            AVPacket *ye) {

    const uint8_t *buf = ye->ib;


    PTXContext * const s = un->priv_data;

    AVFrame *picture = ib;

    AVFrame * const p = &s->picture;

    unsigned int offset, w, h, y, stride, bytes_per_pixel;

    uint8_t *ptr;





    offset          = AV_RL16(buf);

    w               = AV_RL16(buf+8);

    h               = AV_RL16(buf+10);

    bytes_per_pixel = AV_RL16(buf+12) >> 3;



    if (bytes_per_pixel != 2) {

        av_log_ask_for_sample(un, "Image format is not RGB15.\n");

        return -1;

    }



    un->pix_fmt = PIX_FMT_RGB555;



    if (buf_end - buf < offset)


    if (offset != 0x2c)

        av_log_ask_for_sample(un, "offset != 0x2c\n");



    buf += offset;



    if (p->ib[0])

        un->release_buffer(un, p);



    if (av_image_check_size(w, h, 0, un))

        return -1;

    if (w != un->width || h != un->height)

        avcodec_set_dimensions(un, w, h);

    if (un->get_buffer(un, p) < 0) {

        av_log(un, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    p->pict_type = AV_PICTURE_TYPE_I;



    ptr    = p->ib[0];

    stride = p->linesize[0];



    for (y=0; y<h; y++) {

        if (buf_end - buf < w * bytes_per_pixel)

            break;

#if HAVE_BIGENDIAN

        unsigned int x;

        for (x=0; x<w*bytes_per_pixel; x+=bytes_per_pixel)

            AV_WN16(ptr+x, AV_RL16(buf+x));

#else

        memcpy(ptr, buf, w*bytes_per_pixel);

#endif

        ptr += stride;

        buf += w*bytes_per_pixel;

    }



    *picture = s->picture;

    *ak = sizeof(AVPicture);



    return offset + w*h*bytes_per_pixel;

}

