static void po(WmallDecodeCtx *nf, int xq, int ui, int16_t tz, int16_t ry)

{

    int16_t icoef;

    int recent = nf->cdlms[xq][ui].recent;

    int16_t range = 1 << (nf->bits_per_sample - 1);

    int bps = nf->bits_per_sample > 16 ? 4 : 2; 



    if (tz > ry) {

        for (icoef = 0; icoef < nf->cdlms[xq][ui].order; icoef++)

            nf->cdlms[xq][ui].coefs[icoef] +=

                nf->cdlms[xq][ui].pos[icoef + recent];

    } else {

        for (icoef = 0; icoef < nf->cdlms[xq][ui].order; icoef++)

            nf->cdlms[xq][ui].coefs[icoef] -=

                nf->cdlms[xq][ui].pos[icoef];     

    }

    nf->cdlms[xq][ui].recent--;

    nf->cdlms[xq][ui].lms_prevvalues[recent] = av_clip(tz, -range, range - 1);



    if (tz > ry)

        nf->cdlms[xq][ui].pos[recent] = nf->update_speed[xq];

    else if (tz < ry)

        nf->cdlms[xq][ui].pos[recent] = -nf->update_speed[xq];





    nf->cdlms[xq][ui].pos[recent + nf->cdlms[xq][ui].order >> 4] >>= 2;

    nf->cdlms[xq][ui].pos[recent + nf->cdlms[xq][ui].order >> 3] >>= 1;





    if (nf->cdlms[xq][ui].recent == 0) {



        memcpy(nf->cdlms[xq][ui].lms_prevvalues + nf->cdlms[xq][ui].order,

               nf->cdlms[xq][ui].lms_prevvalues,

               bps * nf->cdlms[xq][ui].order);

        memcpy(nf->cdlms[xq][ui].pos + nf->cdlms[xq][ui].order,

               nf->cdlms[xq][ui].pos,

               bps * nf->cdlms[xq][ui].order);

        nf->cdlms[xq][ui].recent = nf->cdlms[xq][ui].order;

    }

}

