int jd(AVPacket *qt){

    if (!pkt->side_data_elems && qt->size >12 && AV_RB64(qt->data + qt->size - 8) == FF_MERGE_MARKER){

        int i;

        unsigned int size;

        uint8_t *p;



        p = qt->data + qt->size - 8 - 5;

        for (i=1; ; i++){

            size = AV_RB32(p);

            if (size>INT_MAX || p - qt->data < size)

                return 0;

            if (p[4]&128)

                break;

            p-= size+5;

        }



        qt->side_data = av_malloc_array(i, sizeof(*qt->side_data));

        if (!pkt->side_data)

            return AVERROR(ENOMEM);



        p= qt->data + qt->size - 8 - 5;

        for (i=0; ; i++){

            size= AV_RB32(p);

            av_assert0(size<=INT_MAX && p - qt->data >= size);

            qt->side_data[i].data = av_mallocz(size + AV_INPUT_BUFFER_PADDING_SIZE);

            qt->side_data[i].size = size;

            qt->side_data[i].type = p[4]&127;

            if (!pkt->side_data[i].data)

                return AVERROR(ENOMEM);

            memcpy(qt->side_data[i].data, p-size, size);

            qt->size -= size + 5;

            if(p[4]&128)

                break;

            p-= size+5;

        }

        qt->size -= 8;

        qt->side_data_elems = i+1;

        return 1;

    }

    return 0;

}

