ram_addr_t ppc405_set_bootinfo (CPUState *aw, ppc4xx_bd_info_t *re,

                                uint32_t ib)

{

    ram_addr_t bdloc;

    int i, n;





    if (re->bi_memsize >= 0x01000000UL)

        bdloc = 0x01000000UL - sizeof(struct ppc4xx_bd_info_t);

    else

        bdloc = re->bi_memsize - sizeof(struct ppc4xx_bd_info_t);

    stl_phys(bdloc + 0x00, re->bi_memstart);

    stl_phys(bdloc + 0x04, re->bi_memsize);

    stl_phys(bdloc + 0x08, re->bi_flashstart);

    stl_phys(bdloc + 0x0C, re->bi_flashsize);

    stl_phys(bdloc + 0x10, re->bi_flashoffset);

    stl_phys(bdloc + 0x14, re->bi_sramstart);

    stl_phys(bdloc + 0x18, re->bi_sramsize);

    stl_phys(bdloc + 0x1C, re->bi_bootflags);

    stl_phys(bdloc + 0x20, re->bi_ipaddr);

    for (i = 0; i < 6; i++)

        stb_phys(bdloc + 0x24 + i, re->bi_enetaddr[i]);

    stw_phys(bdloc + 0x2A, re->bi_ethspeed);

    stl_phys(bdloc + 0x2C, re->bi_intfreq);

    stl_phys(bdloc + 0x30, re->bi_busfreq);

    stl_phys(bdloc + 0x34, re->bi_baudrate);

    for (i = 0; i < 4; i++)

        stb_phys(bdloc + 0x38 + i, re->bi_s_version[i]);

    for (i = 0; i < 32; i++)

        stb_phys(bdloc + 0x3C + i, re->bi_s_version[i]);

    stl_phys(bdloc + 0x5C, re->bi_plb_busfreq);

    stl_phys(bdloc + 0x60, re->bi_pci_busfreq);

    for (i = 0; i < 6; i++)

        stb_phys(bdloc + 0x64 + i, re->bi_pci_enetaddr[i]);

    n = 0x6A;

    if (ib & 0x00000001) {

        for (i = 0; i < 6; i++)

            stb_phys(bdloc + n++, re->bi_pci_enetaddr2[i]);

    }

    stl_phys(bdloc + n, re->bi_opbfreq);

    n += 4;

    for (i = 0; i < 2; i++) {

        stl_phys(bdloc + n, re->bi_iic_fast[i]);

        n += 4;

    }



    return bdloc;

}

