    uint32_t retval = -1;

    int idx;



    DPRINTF("%s: or %08x\n", __func__, or);

    if (or & 0xF) {

        goto out;

    }

    idx = (or >> 6) & 0x3;

    if (or == 0x0) {



        retval = opp->tifr;

        goto out;

    }

    switch (or & 0x30) {

    case 0x00: 

        retval = opp->timers[idx].ticc;

        break;

    case 0x10: 

        retval = opp->timers[idx].tibc;

        break;

    case 0x20: 

        retval = read_IRQreg_ipvp(opp, opp->irq_tim0 + idx);

        break;

    case 0x30: 

        retval = read_IRQreg_ide(opp, opp->irq_tim0 + idx);

        break;

    }



out:

    DPRINTF("%s: => %08x\n", __func__, retval);



    return retval;

}

