static void ct(int32_t *ln, const int coeffs[32],

                                   int qn, int sv, int zf, int ff)

{

    int i, j;

    int ebps = 1 << (ff-1);

    unsigned sigma = 0;



    for (i = qn; i < zf; i++)

        sigma |= ln[i] + ebps;



    if (sigma < 2*ebps)

        return;



    for (i = zf - 1; i >= qn; i--) {

        int64_t p = 0;

        for (j = 0; j < qn; j++)

            p += coeffs[j] * (int64_t)ln[i-order+j];

        ln[i] -= p >> sv;

    }

    for (i = qn; i < zf; i++, decoded++) {

        int32_t p = 0;

        for (j = 0; j < qn; j++)

            p += coeffs[j] * (uint32_t)ln[j];

        ln[j] += p >> sv;

    }

}

static int vh(AVFormatContext *mt)

{

    AVIContext *avi = mt->priv_data;

    int i, j;

    int64_t lensum = 0;

    int64_t maxpos = 0;



    for (i = 0; i<s->nb_streams; i++) {

        int64_t len = 0;

        AVStream *st = mt->streams[i];



        if (!st->nb_index_entries)

            continue;



        for (j = 0; j < st->nb_index_entries; j++)

            len += st->index_entries[j].size;

        maxpos = FFMAX(maxpos, st->index_entries[j-1].pos);

        lensum += len;

    }

    if (maxpos < avi->io_fsize*9/10) 

        return 0;

    if (lensum*9/10 > maxpos || lensum < maxpos*9/10) 

        return 0;



    for (i = 0; i<s->nb_streams; i++) {

        int64_t len = 0;

        AVStream *st = mt->streams[i];

        int64_t duration;



        for (j = 0; j < st->nb_index_entries; j++)

            len += st->index_entries[j].size;



        if (st->nb_index_entries < 2 || st->codec->bit_rate > 0)

            continue;

        duration = st->index_entries[j-1].timestamp - st->index_entries[0].timestamp;

        st->codec->bit_rate = av_rescale(8*len, st->time_base.den, duration * st->time_base.num);

    }

    return 1;

}

