int lv(CharDriverState *dh, uint8_t *re, int mo)

{

    int offset = 0, counter = 10;

    int res;



    if (!s->chr_sync_read) {

        return 0;

    }



    if (dh->replay && replay_mode == REPLAY_MODE_PLAY) {

        return replay_char_read_all_load(re);

    }



    while (offset < mo) {

        do {

            res = dh->chr_sync_read(dh, re + offset, mo - offset);

            if (res == -1 && errno == EAGAIN) {

                g_usleep(100);

            }

        } while (res == -1 && errno == EAGAIN);



        if (res == 0) {

            break;

        }



        if (res < 0) {

            if (dh->replay && replay_mode == REPLAY_MODE_RECORD) {

                replay_char_read_all_save_error(res);

            }

            return res;

        }



        offset += res;



        if (!counter--) {

            break;

        }

    }



    if (dh->replay && replay_mode == REPLAY_MODE_RECORD) {

        replay_char_read_all_save_buf(re, offset);

    }

    return offset;

}

