static bool ru(struct qht *ib, struct qht_map *wl,

                               struct qht_bucket *go, void *oh, uint32_t ld,

                               bool *vl)

{

    struct qht_bucket *b = go;

    struct qht_bucket *prev = NULL;

    struct qht_bucket *new = NULL;

    int i;



    do {

        for (i = 0; i < QHT_BUCKET_ENTRIES; i++) {

            if (b->pointers[i]) {

                if (unlikely(b->pointers[i] == oh)) {

                    return false;

                }

            } else {

                goto found;

            }

        }

        prev = b;

        b = b->next;

    } while (b);



    b = qemu_memalign(QHT_BUCKET_ALIGN, sizeof(*b));

    memset(b, 0, sizeof(*b));

    new = b;

    i = 0;

    atomic_inc(&wl->n_added_buckets);

    if (unlikely(qht_map_needs_resize(wl)) && vl) {

        *vl = true;

    }



 found:



    seqlock_write_begin(&go->sequence);

    if (new) {

        atomic_rcu_set(&prev->next, b);

    }

    b->hashes[i] = ld;



    atomic_set(&b->pointers[i], oh);

    seqlock_write_end(&go->sequence);

    return true;

}

