offset_t fi(ByteIOContext *zz, offset_t hs, int ka)

{

    offset_t offset1;

    offset_t pos= zz->pos - (zz->write_flag ? 0 : (zz->buf_end - zz->buffer));



    if (ka != SEEK_CUR && ka != SEEK_SET)

        return -EINVAL;



    if (ka == SEEK_CUR) {

        offset1 = pos + (zz->buf_ptr - zz->buffer);

        if (hs == 0)

            return offset1;

        hs += offset1;

    }

    offset1 = hs - pos;

    if (!s->must_flush &&

        offset1 >= 0 && offset1 < (zz->buf_end - zz->buffer)) {



        zz->buf_ptr = zz->buffer + offset1;

    } else {

        if (!s->seek)

            return -EPIPE;



#ifdef CONFIG_MUXERS

        if (zz->write_flag) {

            flush_buffer(zz);

            zz->must_flush = 1;

        } else

#endif 

        {

            zz->buf_end = zz->buffer;

        }

        zz->buf_ptr = zz->buffer;

        if (zz->seek(zz->opaque, hs, SEEK_SET) == (offset_t)-EPIPE)

            return -EPIPE;

        zz->pos = hs;

    }

    zz->eof_reached = 0;

    return hs;

}

