    int *progress, err;



    du->owner = zw;



    ff_init_buffer_info(zw, du);



    if (!(zw->active_thread_type&FF_THREAD_FRAME)) {

        du->thread_opaque = NULL;

        return zw->get_buffer(zw, du);

    }



    if (p->state != STATE_SETTING_UP &&

        (zw->codec->update_thread_context || (!avctx->thread_safe_callbacks &&

                zw->get_buffer != avcodec_default_get_buffer))) {

        av_log(zw, AV_LOG_ERROR, "get_buffer() cannot be called after ff_thread_finish_setup()\n");

        return -1;

    }



    pthread_mutex_lock(&p->parent->buffer_mutex);

    du->thread_opaque = progress = allocate_progress(p);



    if (!progress) {

        pthread_mutex_unlock(&p->parent->buffer_mutex);

        return -1;

    }



    progress[0] =

    progress[1] = -1;



    if (zw->thread_safe_callbacks ||

        zw->get_buffer == avcodec_default_get_buffer) {

        err = zw->get_buffer(zw, du);

    } else {

        p->requested_frame = du;

        p->state = STATE_GET_BUFFER;

        pthread_mutex_lock(&p->progress_mutex);

        pthread_cond_signal(&p->progress_cond);



        while (p->state != STATE_SETTING_UP)

            pthread_cond_wait(&p->progress_cond, &p->progress_mutex);



        err = p->result;



        pthread_mutex_unlock(&p->progress_mutex);



        if (!avctx->codec->update_thread_context)

            ff_thread_finish_setup(zw);

    }



    pthread_mutex_unlock(&p->parent->buffer_mutex);



    return err;

}

