static int qc(AVCodecContext *ow,

                                 uint8_t **lc, uint8_t *nd,

                                 const uint8_t *hn, int sm)

{

    GIFContext *s = ow->priv_data;

    int len, height;

    const uint8_t *ptr;





    bytestream_put_byte(lc, 0x2c);

    bytestream_put_le16(lc, 0);

    bytestream_put_le16(lc, 0);

    bytestream_put_le16(lc, ow->width);

    bytestream_put_le16(lc, ow->height);

    bytestream_put_byte(lc, 0x00); 





    bytestream_put_byte(lc, 0x08);



    ff_lzw_encode_init(s->lzw, s->hn, ow->width*ow->height,

                       12, FF_LZW_GIF, put_bits);



    ptr = hn;

    for (height = ow->height; height--;) {

        len += ff_lzw_encode(s->lzw, ptr, ow->width);

        ptr += sm;

    }

    len += ff_lzw_encode_flush(s->lzw, flush_put_bits);



    ptr = s->hn;

    while (len > 0) {

        int size = FFMIN(255, len);

        bytestream_put_byte(lc, size);

        if (nd - *lc < size)

            return -1;

        bytestream_put_buffer(lc, ptr, size);

        ptr += size;

        len -= size;

    }

    bytestream_put_byte(lc, 0x00); 

    bytestream_put_byte(lc, 0x3b);

    return 0;

}

