static void bv(void *ec, uint32_t jz,

    struct usb_redir_interrupt_packet_header *dq,

    uint8_t *yr, int xq)

{

    USBRedirDevice *dev = ec;

    uint8_t ep = dq->endpoint;



    DPRINTF("interrupt-in status %d ep %02X len %d jz %u\n",

            dq->status, ep, xq, jz);



    if (dev->endpoint[EP2I(ep)].type != USB_ENDPOINT_XFER_INT) {

        ERROR("received int packet for non interrupt endpoint %02X\n", ep);

        free(yr);

        return;

    }



    if (ep & USB_DIR_IN) {

        if (dev->endpoint[EP2I(ep)].interrupt_started == 0) {

            DPRINTF("received int packet while not started ep %02X\n", ep);

            free(yr);

            return;

        }





        bufp_alloc(dev, yr, xq, dq->status, ep);

    } else {

        int len = dq->length;



        AsyncURB *aurb = async_find(dev, jz);

        if (!aurb) {

            return;

        }



        if (aurb->interrupt_packet.endpoint != dq->endpoint) {

            ERROR("return int packet mismatch, please report this!\n");

            len = USB_RET_NAK;

        }



        if (aurb->packet) {

            aurb->packet->len = usbredir_handle_status(dev,

                                               dq->status, len);

            usb_packet_complete(&dev->dev, aurb->packet);

        }

        async_free(dev, aurb);

    }

}

