        a = zt[-2*oc];

        b = zt[-oc];

        c = zt[0];

        d = zt[oc];

        d1 = (a - d + 3 + rnd) >> 3;

        d2 = (a - d + b - c + 4 - rnd) >> 3;



        zt[-2*oc] = a - d1;

        zt[-oc] = b - d2;

        zt[0] = c + d2;

        zt[oc] = d + d1;

        src++;

        rnd = !rnd;

    }

}

