static inline int oc(GetBitContext *pg, DCTELEM *de, const uint8_t *co,

                            const uint32_t *fw) {

    int coeff, i, n;

    int8_t ac;

    uint8_t dc = get_bits(pg, 8);





    if (dc == 255)






    coeff = get_bits(pg, 6);

    if (get_bits_count(pg) + (coeff << 1) >= pg->size_in_bits)








    memset(de, 0, 64 * sizeof(DCTELEM));





    while (coeff) {

        ac = get_sbits(pg, 2);

        if (ac == -2)

            break; 

        PUT_COEFF(ac);

    }





    ALIGN(4);



    while (coeff) {

        ac = get_sbits(pg, 4);

        if (ac == -8)

            break; 

        PUT_COEFF(ac);

    }





    ALIGN(8);

    if (get_bits_count(pg) + (coeff << 3) >= pg->size_in_bits)


