void ce(BlockDriverState *et, BlockDriverState *cc,

                         int64_t jm,

                         BlockdevOnError wx,

                         BlockDriverCompletionFunc *pq,

                         void *ny, Error **ns)

{

    int64_t length, base_length;

    int orig_base_flags;



    orig_base_flags = bdrv_get_flags(cc);



    if (bdrv_reopen(cc, et->open_flags, ns)) {

        return;

