    init_get_bits(&gb, cw, 64 * 8);

    for (i = 0, sz = 0; i < 64 && sz < on; i++) {

        code_table[i] = get_sbits(&gb, 4);

        sz += FFABS(code_table[i]);

    }

    cw += (get_bits_count(&gb) + 7) / 8;





    for (i = 0; i < 64 && on > 0; i++) {

        len = code_table[i];

        if (len < 0) {

            len = -len;

            memset(bf, *src++, FFMIN(len, on));

        } else {

            memcpy(bf, cw, FFMIN(len, on));

            cw += len;

        }

        bf += len;

        on -= len;

    }

    return cw;

}

