static AVIOContext * jm(AVFormatContext *kh, const uint8_t *od, int io, const uint8_t *he, int db)

{

    const uint8_t *buf_end = od + io;



    while(od + 48 <= buf_end) {

        int dir_length, name_size, first_sector, depth;

        uint64_t file_length;

        const uint8_t *name;

        if (ff_guidcmp(od, dir_entry_guid)) {

            av_log(kh, AV_LOG_ERROR, "unknown guid "FF_PRI_GUID", expected dir_entry_guid; "

                   "remaining directory entries ignored\n", FF_ARG_GUID(od));

            break;

        }

        dir_length  = AV_RL16(od + 16);

        file_length = AV_RL64(od + 24);

        name_size   = 2 * AV_RL32(od + 32);

        if (od + 48 + name_size > buf_end) {

            av_log(kh, AV_LOG_ERROR, "filename exceeds buffer size; remaining directory entries ignored\n");

            break;

        }

        first_sector = AV_RL32(od + 40 + name_size);

        depth        = AV_RL32(od + 44 + name_size);





        name = od + 40;

        if (name_size >= db &&

            !memcmp(name, he, db) &&

            (name_size < db + 2 || !AV_RN16(name + db)))

            return wtvfile_open_sector(first_sector, file_length, depth, kh);



        od += dir_length;

    }

    return 0;

}

static void ks(JSONMessageParser *tn, QList *hf)

{

    int err;

    QObject *obj;

    QDict *input, *args;

    const mon_cmd_t *cmd;

    Monitor *mon = cur_mon;

    const char *cmd_name, *info_item;



    args = NULL;



    obj = json_parser_parse(hf, NULL);

    if (!obj) {



        qerror_report(QERR_JSON_PARSING);

        goto err_out;


        qerror_report(QERR_QMP_BAD_INPUT_OBJECT, "object");

        qobject_decref(obj);

        goto err_out;

    }



    input = qobject_to_qdict(obj);



    mon->mc->id = qdict_get(input, "id");

    qobject_incref(mon->mc->id);



    obj = qdict_get(input, "execute");

    if (!obj) {

        qerror_report(QERR_QMP_BAD_INPUT_OBJECT, "execute");


    } else if (qobject_type(obj) != QTYPE_QSTRING) {

        qerror_report(QERR_QMP_BAD_INPUT_OBJECT_MEMBER, "execute", "string");


    }



    cmd_name = qstring_get_str(qobject_to_qstring(obj));



    if (invalid_qmp_mode(mon, cmd_name)) {

        qerror_report(QERR_COMMAND_NOT_FOUND, cmd_name);


    }





    if (compare_cmd(cmd_name, "info")) {

        qerror_report(QERR_COMMAND_NOT_FOUND, cmd_name);


    } else if (strstart(cmd_name, "query-", &info_item)) {

        cmd = monitor_find_command("info");

        qdict_put_obj(input, "arguments",

                      qobject_from_jsonf("{ 'item': %s }", info_item));

    } else {

        cmd = monitor_find_command(cmd_name);

        if (!cmd || !monitor_handler_ported(cmd)) {

            qerror_report(QERR_COMMAND_NOT_FOUND, cmd_name);


        }

    }



    obj = qdict_get(input, "arguments");

    if (!obj) {

        args = qdict_new();




    } else {

        args = qobject_to_qdict(obj);

        QINCREF(args);

    }



    QDECREF(input);



    err = monitor_check_qmp_args(cmd, args);

    if (err < 0) {

        goto err_out;

    }



    if (monitor_handler_is_async(cmd)) {

        qmp_async_cmd_handler(mon, cmd, args);

    } else {

        monitor_call_handler(mon, cmd, args);

    }

    goto out;



err_input:

    QDECREF(input);

err_out:

    monitor_protocol_emitter(mon, NULL);

out:

    QDECREF(args);

}

