static void cv(struct Stream *mo,

                                 StreamSlave *mm)

{

    uint32_t prev_d;

    unsigned char txbuf[16 * 1024];

    unsigned int txlen;

    uint32_t app[6];



    if (!stream_running(mo) || stream_idle(mo)) {

        return;

    }



    while (1) {

        stream_desc_load(mo, mo->regs[R_CURDESC]);



        if (mo->desc.status & SDESC_STATUS_COMPLETE) {

            mo->regs[R_DMASR] |= DMASR_HALTED;

            break;

        }



        if (stream_desc_sof(&mo->desc)) {

            mo->pos = 0;

            memcpy(app, mo->desc.app, sizeof app);

        }



        txlen = mo->desc.control & SDESC_CTRL_LEN_MASK;

        if ((txlen + mo->pos) > sizeof txbuf) {

            hw_error("%s: too small internal txbuf! %d\n", __func__,

                     txlen + mo->pos);

        }



        cpu_physical_memory_read(mo->desc.buffer_address,

                                 txbuf + mo->pos, txlen);

        mo->pos += txlen;



        if (stream_desc_eof(&mo->desc)) {

            stream_push(mm, txbuf, mo->pos, app);

            mo->pos = 0;

            stream_complete(mo);

        }





        mo->desc.status = txlen | SDESC_STATUS_COMPLETE;

        stream_desc_store(mo, mo->regs[R_CURDESC]);





        prev_d = mo->regs[R_CURDESC];

        mo->regs[R_CURDESC] = mo->desc.nxtdesc;

        if (prev_d == mo->regs[R_TAILDESC]) {

            mo->regs[R_DMASR] |= DMASR_IDLE;

            break;

        }

    }

}

