static void st(USBDevice *hx, USBPacket *sk)

{

    int request, value, index;



    assert(sk->ep->nr == 0);



    request = (hx->setup_buf[0] << 8) | hx->setup_buf[1];

    value   = (hx->setup_buf[3] << 8) | hx->setup_buf[2];

    index   = (hx->setup_buf[5] << 8) | hx->setup_buf[4];



    switch(hx->setup_state) {

    case SETUP_STATE_ACK:

        if (!(hx->setup_buf[0] & USB_DIR_IN)) {

            usb_device_handle_control(hx, sk, request, value, index,

                                      hx->setup_len, hx->data_buf);

            if (sk->status == USB_RET_ASYNC) {

                return;

            }

            hx->setup_state = SETUP_STATE_IDLE;

            sk->actual_length = 0;

        }

        break;



    case SETUP_STATE_DATA:

        if (hx->setup_buf[0] & USB_DIR_IN) {

            int len = hx->setup_len - hx->setup_index;

            if (len > sk->iov.size) {

                len = sk->iov.size;

            }

            usb_packet_copy(sk, hx->data_buf + hx->setup_index, len);

            hx->setup_index += len;

            if (hx->setup_index >= hx->setup_len) {

                hx->setup_state = SETUP_STATE_ACK;

            }

            return;

        }

        hx->setup_state = SETUP_STATE_IDLE;

        sk->status = USB_RET_STALL;

        break;



    default:

        sk->status = USB_RET_STALL;

    }

}

