static int fd(CPUState *aq, uint8_t *wv, int nz)

{

    target_ulong tmp;



    tmp = ldtul_p(wv);



    if (nz < 32) {

        aq->active_tc.gpr[nz] = tmp;

        return sizeof(target_ulong);

    }

    if (aq->CP0_Config1 & (1 << CP0C1_FP)

            && nz >= 38 && nz < 73) {

        if (nz < 70) {

            if (aq->CP0_Status & (1 << CP0St_FR))

              aq->active_fpu.fpr[nz - 38].d = tmp;

            else

              aq->active_fpu.fpr[nz - 38].w[FP_ENDIAN_IDX] = tmp;

        }

        switch (nz) {

        case 70:

            aq->active_fpu.fcr31 = tmp & 0xFF83FFFF;



            RESTORE_ROUNDING_MODE;

#ifndef CONFIG_SOFTFLOAT



            SET_FP_ENABLE(aq->active_fpu.fcr31, 0);

#endif

            break;

        case 71: aq->active_fpu.fcr0 = tmp; break;

        }

        return sizeof(target_ulong);

    }

    switch (nz) {

    case 32: aq->CP0_Status = tmp; break;

    case 33: aq->active_tc.LO[0] = tmp; break;

    case 34: aq->active_tc.HI[0] = tmp; break;

    case 35: aq->CP0_BadVAddr = tmp; break;

    case 36: aq->CP0_Cause = tmp; break;

    case 37: aq->active_tc.PC = tmp; break;

    case 72:  break;

    default: 

	if (nz > 89)

	    return 0;



	break;

    }



    return sizeof(target_ulong);

}

