    cbp_b = mr->slice_table[mr->top_mb_xy]     == mr->slice_num ? mr->top_cbp  : -1;



    ctx = !(cbp_a & 0x02) + 2 * !(cbp_b & 0x04);

    cbp |= get_cabac_noinline(&mr->cabac, &mr->cabac_state[73 + ctx]);

    ctx = !(cbp   & 0x01) + 2 * !(cbp_b & 0x08);

    cbp |= get_cabac_noinline(&mr->cabac, &mr->cabac_state[73 + ctx]) << 1;

