    cbp |= get_cabac_noinline(&mr->cabac, &mr->cabac_state[73 + ctx]) << 2;

    ctx = !(cbp   & 0x04) + 2 * !(cbp   & 0x02);

    cbp |= get_cabac_noinline(&mr->cabac, &mr->cabac_state[73 + ctx]) << 3;

    return cbp;

