static float vb(uint8_t *qb, int hg,

                        uint8_t *ws, int pi,

                        int bc, int vi, void *rs)

{

    int z = 0;

    int x, y;

    float ssim = 0.0;

    int (*sum0)[4] = rs;

    int (*sum1)[4] = sum0 + (bc >> 2) + 3;



    bc >>= 2;

    vi >>= 2;



    for (y = 1; y < vi; y++) {

        for (; z <= y; z++) {

            FFSWAP(void*, sum0, sum1);

            for (x = 0; x < bc; x+=2)

                ssim_4x4x2_core(&qb[4 * (x + z * hg)], hg,

                                &ws[4 * (x + z * pi)], pi,

                                &sum0[x]);

        }



        ssim += ssim_endn(sum0, sum1, bc - 1);

    }



    return ssim / ((vi - 1) * (bc - 1));

}

