    uint32_t adsr, len;

    int i;



    if (!(xl & 4)) {

        s->tmpblit = bd;

    } else {

        xl = (xl >> 3) & 0xfffff;

        adsr = bd & 0xffffff;

        len = ((bd >> 24) & 0x1f) + 1;

        if (adsr == 0xffffff) {

            memset(&s->vram[xl], s->tmpblit, len);

