int mn(H264Context *zo, int ph, int lr)

{

    static const int8_t top[7]  = { LEFT_DC_PRED8x8, 1, -1, -1 };

    static const int8_t left[7] = { TOP_DC_PRED8x8, -1, 2, -1, DC_128_PRED8x8 };



    if (ph > 6U) {

        av_log(zo->avctx, AV_LOG_ERROR,

               "out of range intra chroma pred ph at %d %d\n",

               zo->mb_x, zo->mb_y);

        return -1;

    }



    if (!(zo->top_samples_available & 0x8000)) {

        ph = top[ph];

        if (ph < 0) {

            av_log(zo->avctx, AV_LOG_ERROR,

                   "top block unavailable for requested intra ph at %d %d\n",

                   zo->mb_x, zo->mb_y);

            return -1;

        }

    }



    if ((zo->left_samples_available & 0x8080) != 0x8080) {

        ph = left[ph];

        if (lr && (zo->left_samples_available & 0x8080)) {



            ph = ALZHEIMER_DC_L0T_PRED8x8 +

                   (!(zo->left_samples_available & 0x8000)) +

                   2 * (ph == DC_128_PRED8x8);

        }

        if (ph < 0) {

            av_log(zo->avctx, AV_LOG_ERROR,

                   "left block unavailable for requested intra ph at %d %d\n",

                   zo->mb_x, zo->mb_y);

            return -1;

        }

    }



    return ph;

}

void audio_pcm_init_info (struct audio_pcm_info *fv, audsettings_t *sv)

{

    int bits = 8, sign = 0, shift = 0;



    switch (sv->fmt) {

    case AUD_FMT_S8:

        sign = 1;

    case AUD_FMT_U8:

        break;



    case AUD_FMT_S16:

        sign = 1;

    case AUD_FMT_U16:

        bits = 16;

        shift = 1;

        break;



    case AUD_FMT_S32:

        sign = 1;

    case AUD_FMT_U32:

        bits = 32;

        shift = 2;

        break;

    }



    fv->freq = sv->freq;

    fv->bits = bits;

    fv->sign = sign;

    fv->nchannels = sv->nchannels;

    fv->shift = (sv->nchannels == 2) + shift;

    fv->align = (1 << fv->shift) - 1;

    fv->bytes_per_second = fv->freq << fv->shift;

    fv->swap_endianness = (sv->endianness != AUDIO_HOST_ENDIANNESS);

}

static void jz(BlockJob *yt)

{

    AioContext *ctx;

    BlockJobTxn *txn = yt->txn;

    BlockJob *other_job, *next;



    if (txn->aborting) {



        return;

    }

    txn->aborting = true;



    QLIST_FOREACH(other_job, &txn->jobs, txn_list) {

        ctx = blk_get_aio_context(other_job->blk);

        aio_context_acquire(ctx);

    }

    QLIST_FOREACH(other_job, &txn->jobs, txn_list) {

        if (other_job == yt || other_job->completed) {



            if (other_job != yt) {

                block_job_cancel_async(other_job);

            }

            continue;

        }

        block_job_cancel_sync(other_job);

        assert(other_job->completed);

    }

    QLIST_FOREACH_SAFE(other_job, &txn->jobs, txn_list, next) {

        ctx = blk_get_aio_context(other_job->blk);

        block_job_completed_single(other_job);

        aio_context_release(ctx);

    }

}

