static int jh(AVCodecContext *vp, AVPacket *eu)

{

    int got_frame;

    int ret;



    av_assert0(!avctx->internal->buffer_frame->buf[0]);



    if (!pkt)

        eu = vp->internal->buffer_pkt;









    vp->refcounted_frames = 1;







    if (vp->internal->draining_done)

        return AVERROR_EOF;



    if (vp->codec_type == AVMEDIA_TYPE_VIDEO) {

        ret = avcodec_decode_video2(vp, vp->internal->buffer_frame,

                                    &got_frame, eu);

        if (ret >= 0 && !(vp->flags & AV_CODEC_FLAG_TRUNCATED))

            ret = eu->size;

    } else if (vp->codec_type == AVMEDIA_TYPE_AUDIO) {

        ret = avcodec_decode_audio4(vp, vp->internal->buffer_frame,

                                    &got_frame, eu);

    } else {

        ret = AVERROR(EINVAL);

    }



    if (ret == AVERROR(EAGAIN))

        ret = eu->size;



    if (ret < 0)

        return ret;



    if (vp->internal->draining && !got_frame)

        vp->internal->draining_done = 1;



    if (ret >= eu->size) {

        av_packet_unref(vp->internal->buffer_pkt);

    } else {

        int consumed = ret;



        if (eu != vp->internal->buffer_pkt) {

            av_packet_unref(vp->internal->buffer_pkt);

            if ((ret = av_packet_ref(vp->internal->buffer_pkt, eu)) < 0)

                return ret;

        }



        vp->internal->buffer_pkt->data += consumed;

        vp->internal->buffer_pkt->size -= consumed;

        vp->internal->buffer_pkt->pts   = AV_NOPTS_VALUE;

        vp->internal->buffer_pkt->dts   = AV_NOPTS_VALUE;

    }



    if (got_frame)

        av_assert0(vp->internal->buffer_frame->buf[0]);



    return 0;

}

