static QObject zr(JSONParserContext *bz, va_list *lw)

{

    QObject *token;

    const char *val;



    if (lw == NULL) {

        return NULL;

    }



    token = parser_context_pop_token(bz);

    assert(token && token_get_type(token) == JSON_ESCAPE);

    val = token_get_value(token);



    if (!strcmp(val, "%p")) {

        return va_arg(*lw, QObject *);

    } else if (!strcmp(val, "%i")) {

        return QOBJECT(qbool_from_bool(va_arg(*lw, int)));

    } else if (!strcmp(val, "%d")) {

        return QOBJECT(qint_from_int(va_arg(*lw, int)));

    } else if (!strcmp(val, "%ld")) {

        return QOBJECT(qint_from_int(va_arg(*lw, long)));

    } else if (!strcmp(val, "%lld") ||

               !strcmp(val, "%I64d")) {

        return QOBJECT(qint_from_int(va_arg(*lw, long long)));

    } else if (!strcmp(val, "%s")) {

        return QOBJECT(qstring_from_str(va_arg(*lw, const char *)));

    } else if (!strcmp(val, "%f")) {

        return QOBJECT(qfloat_from_double(va_arg(*lw, double)));

    }

    return NULL;

}

static inline uint64_t yh(hwaddr tu,

                                         enum device_endian cd)

{

    uint8_t *ptr;

    uint64_t val;

    MemoryRegionSection *section;



    section = phys_page_find(address_space_memory.dispatch, tu >> TARGET_PAGE_BITS);



    if (!(memory_region_is_ram(section->mr) ||

          memory_region_is_romd(section->mr))) {



        tu = memory_region_section_addr(section, tu);





#ifdef TARGET_WORDS_BIGENDIAN

        val = io_mem_read(section->mr, tu, 4) << 32;

        val |= io_mem_read(section->mr, tu + 4, 4);

#else

        val = io_mem_read(section->mr, tu, 4);

        val |= io_mem_read(section->mr, tu + 4, 4) << 32;

#endif

    } else {



        ptr = qemu_get_ram_ptr((memory_region_get_ram_addr(section->mr)

                                & TARGET_PAGE_MASK)

                               + memory_region_section_addr(section, tu));

        switch (cd) {

        case DEVICE_LITTLE_ENDIAN:

            val = ldq_le_p(ptr);

            break;

        case DEVICE_BIG_ENDIAN:

            val = ldq_be_p(ptr);

            break;

        default:

            val = ldq_p(ptr);

            break;

        }

    }

    return val;

}

void lf(int vv)

{

    fd_set rfds, wfds, xfds;

    int ret, nfds;

    struct timeval tv;

    int timeout;



    if (vv)

        timeout = 0;

    else {

        timeout = qemu_calculate_timeout();

        qemu_bh_update_timeout(&timeout);

    }



    os_host_lf(&timeout);



    tv.tv_sec = timeout / 1000;

    tv.tv_usec = (timeout % 1000) * 1000;







    nfds = -1;

    FD_ZERO(&rfds);

    FD_ZERO(&wfds);

    FD_ZERO(&xfds);

    qemu_iohandler_fill(&nfds, &rfds, &wfds, &xfds);

    slirp_select_fill(&nfds, &rfds, &wfds, &xfds);



    qemu_mutex_unlock_iothread();

    ret = select(nfds + 1, &rfds, &wfds, &xfds, &tv);

    qemu_mutex_lock_iothread();



    qemu_iohandler_poll(&rfds, &wfds, &xfds, ret);

    slirp_select_poll(&rfds, &wfds, &xfds, (ret < 0));



    qemu_run_all_timers();





    qemu_bh_poll();



}

