static int da(AVCodecContext *uv, uint8_t *um,

                             int yk, void *zn)

{

    AlacEncodeContext *s = uv->priv_data;

    PutBitContext *pb = &s->pbctx;

    int i, out_bytes, verbatim_flag = 0;



    if (uv->frame_size > DEFAULT_FRAME_SIZE) {

        av_log(uv, AV_LOG_ERROR, "input um size exceeded\n");

        return -1;

    }



    if (yk < 2 * s->max_coded_frame_size) {

        av_log(uv, AV_LOG_ERROR, "buffer size is too small\n");

        return -1;

    }



verbatim:

    init_put_bits(pb, um, yk);



    if (s->compression_level == 0 || verbatim_flag) {



        const int16_t *samples = zn;

        write_frame_header(s, 1);

        for (i = 0; i < uv->frame_size * uv->channels; i++) {

            put_sbits(pb, 16, *samples++);

        }

    } else {

        init_sample_buffers(s, zn);

        write_frame_header(s, 0);

        write_compressed_frame(s);

    }



    put_bits(pb, 3, 7);

    flush_put_bits(pb);

    out_bytes = put_bits_count(pb) >> 3;



    if (out_bytes > s->max_coded_frame_size) {



        if (verbatim_flag || s->compression_level == 0) {



            av_log(uv, AV_LOG_ERROR, "error encoding frame\n");

            return -1;

        }

        verbatim_flag = 1;

        goto verbatim;

    }



    return out_bytes;

}

