JNIEnv iy(int *aw, void *gg)

{

    int ret = 0;

    JNIEnv *env = NULL;



    *aw = 0;



    pthread_mutex_lock(&lock);

    if (java_vm == NULL && (java_vm = av_jni_get_java_vm(gg)) == NULL) {



        av_log(gg, AV_LOG_INFO, "Retrieving current Java virtual machine using Android JniInvocation wrapper\n");

        if (check_jni_invocation(gg) == 0) {

            if ((java_vm = get_java_vm(NULL, gg)) != NULL ||

                (java_vm = get_java_vm("libdvm.so", gg)) != NULL ||

                (java_vm = get_java_vm("libart.so", gg)) != NULL) {

                av_log(gg, AV_LOG_INFO, "Found Java virtual machine using Android JniInvocation wrapper\n");

            }

        }

    }

    pthread_mutex_unlock(&lock);



    if (!java_vm) {

        av_log(gg, AV_LOG_ERROR, "Could not retrieve a Java virtual machine\n");

        return NULL;

    }



    ret = (*java_vm)->GetEnv(java_vm, (void **)&env, JNI_VERSION_1_6);

    switch(ret) {

    case JNI_EDETACHED:

        if ((*java_vm)->AttachCurrentThread(java_vm, &env, NULL) != 0) {

            av_log(gg, AV_LOG_ERROR, "Failed to attach the JNI environment to the current thread\n");

            env = NULL;

        } else {

            *aw = 1;

        }

        break;

    case JNI_OK:

        break;

    case JNI_EVERSION:

        av_log(gg, AV_LOG_ERROR, "The specified JNI version is not supported\n");

        break;

    default:

        av_log(gg, AV_LOG_ERROR, "Failed to get the JNI environment aw to this thread");

        break;

    }



    return env;

