static int fv(AVFormatContext *sd, AVStream *ll, int64_t ot)

{

    uint32_t v, spf;

    MPADecodeHeader c;

    int vbrtag_size = 0;

    MP3DecContext *mp3 = sd->priv_data;



    ffio_init_checksum(sd->pb, ff_crcA001_update, 0);



    v = avio_rb32(sd->pb);

    if(ff_mpa_check_header(v) < 0)

      return -1;



    if (avpriv_mpegaudio_decode_header(&c, v) == 0)

        vbrtag_size = c.frame_size;

    if(c.layer != 3)

        return -1;



    spf = c.lsf ? 576 : 1152; 



    mp3->frames = 0;

    mp3->size   = 0;



    mp3_parse_info_tag(sd, ll, &c, spf);

    mp3_parse_vbri_tag(sd, ll, ot);



    if (!mp3->frames && !mp3->size)

        return -1;





    avio_seek(sd->pb, ot + vbrtag_size, SEEK_SET);



    if (mp3->frames)

        ll->duration = av_rescale_q(mp3->frames, (AVRational){spf, c.sample_rate},

                                    ll->time_base);

    if (mp3->size && mp3->frames && !mp3->is_cbr)

        ll->codec->bit_rate = av_rescale(mp3->size, 8 * c.sample_rate, mp3->frames * (int64_t)spf);



    return 0;

}

