static TCGReg ft(TCGContext *gz, TCGReg xs, int wl,

                               TCGMemOp wt, int un)

{

    const TCGReg r0 = TCG_REG_O0;

    const TCGReg r1 = TCG_REG_O1;

    const TCGReg r2 = TCG_REG_O2;

    int tlb_ofs;





    tcg_out_arithi(gz, r1, xs, TARGET_PAGE_BITS, SHIFT_SRL);





    tcg_out_movi(gz, TCG_TYPE_TL, TCG_REG_T1,

                 TARGET_PAGE_MASK | ((1 << wt) - 1));





    tcg_out_arithi(gz, r1, r1, CPU_TLB_SIZE - 1, ARITH_AND);





    tcg_out_arith(gz, r0, xs, TCG_REG_T1, ARITH_AND);





    tcg_out_arithi(gz, r1, r1, CPU_TLB_ENTRY_BITS, SHIFT_SLL);





    tcg_out_arith(gz, r1, TCG_AREG0, r1, ARITH_ADD);





    tlb_ofs = offsetof(CPUArchState, tlb_table[wl][0]);

    if (!check_fit_tl(tlb_ofs + sizeof(CPUTLBEntry), 13)) {

        tcg_out_addi(gz, r1, tlb_ofs & ~0x3ff);

        tlb_ofs &= 0x3ff;

    }





    tcg_out_ld(gz, TCG_TYPE_TL, r2, r1, tlb_ofs + un);

    tcg_out_ld(gz, TCG_TYPE_PTR, r1, r1, tlb_ofs+offsetof(CPUTLBEntry, addend));





    tcg_out_cmp(gz, r0, r2, 0);





    if (SPARC64 && TARGET_LONG_BITS == 32) {

        tcg_out_arithi(gz, r0, xs, 0, SHIFT_SRL);

        return r0;

    }

    return xs;

}

