static void pe(GetByteContext *we, RangeCoder *he, unsigned wk, unsigned hy, unsigned vm)

{

    int t = he->range * (uint64_t)wk / vm;



    he->code1 += t + 1;

    he->range = he->range * (uint64_t)(hy + wk) / vm - (t + 1);



    while (he->range < TOP && bytestream2_get_bytes_left(we) > 0) {

