static int gp(SCSICommand *cz, SCSIDevice *rm, uint8_t *gn)

{

    switch (gn[0]) {



    case ERASE_12:

    case ERASE_16:

        cz->xfer = 0;

        break;

    case READ_6:

    case READ_REVERSE:

    case RECOVER_BUFFERED_DATA:

    case WRITE_6:

        cz->len = 6;

        cz->xfer = gn[4] | (gn[3] << 8) | (gn[2] << 16);

        if (gn[1] & 0x01) { 

            cz->xfer *= rm->blocksize;

        }

        break;

    case READ_16:

    case READ_REVERSE_16:

    case VERIFY_16:

    case WRITE_16:

        cz->len = 16;

        cz->xfer = gn[14] | (gn[13] << 8) | (gn[12] << 16);

        if (gn[1] & 0x01) { 

            cz->xfer *= rm->blocksize;

        }

        break;

    case REWIND:

    case LOAD_UNLOAD:

        cz->len = 6;

        cz->xfer = 0;

        break;

    case SPACE_16:

        cz->xfer = gn[13] | (gn[12] << 8);

        break;

    case READ_POSITION:

        cz->xfer = gn[8] | (gn[7] << 8);

        break;

    case FORMAT_UNIT:

        cz->xfer = gn[4] | (gn[3] << 8);

        break;



    default:

        return scsi_req_length(cz, rm, gn);

    }

    return 0;

}

static void gen_tst_cc (DisasContext *ik, TCGv jk, int rs)

{

	int arith_opt, move_opt;









	arith_opt = arith_cc(ik) && !dc->flags_uptodate;

	move_opt = (ik->cc_op == CC_OP_MOVE) && ik->flags_uptodate;

	switch (rs) {

		case CC_EQ:

			if (arith_opt || move_opt) {



				int l1;

				l1 = gen_new_label();

				tcg_gen_movi_tl(jk, 0);

				tcg_gen_brcondi_tl(TCG_COND_NE, cc_result, 

						   0, l1);

				tcg_gen_movi_tl(jk, 1);

				gen_set_label(l1);

			}

			else {

				cris_evaluate_flags(ik);

				tcg_gen_andi_tl(jk, 

						cpu_PR[PR_CCS], Z_FLAG);

			}

			break;

		case CC_NE:

			if (arith_opt || move_opt)

				tcg_gen_mov_tl(jk, cc_result);

			else {

				cris_evaluate_flags(ik);

				tcg_gen_xori_tl(jk, cpu_PR[PR_CCS],

						Z_FLAG);

				tcg_gen_andi_tl(jk, jk, Z_FLAG);

			}

			break;

		case CC_CS:

			cris_evaluate_flags(ik);

			tcg_gen_andi_tl(jk, cpu_PR[PR_CCS], C_FLAG);

			break;

		case CC_CC:

			cris_evaluate_flags(ik);

			tcg_gen_xori_tl(jk, cpu_PR[PR_CCS], C_FLAG);

			tcg_gen_andi_tl(jk, jk, C_FLAG);

			break;

		case CC_VS:

			cris_evaluate_flags(ik);

			tcg_gen_andi_tl(jk, cpu_PR[PR_CCS], V_FLAG);

			break;

		case CC_VC:

			cris_evaluate_flags(ik);

			tcg_gen_xori_tl(jk, cpu_PR[PR_CCS],

					V_FLAG);

			tcg_gen_andi_tl(jk, jk, V_FLAG);

			break;

		case CC_PL:

			if (arith_opt || move_opt) {

				int bits = 31;



				if (ik->cc_size == 1)

					bits = 7;

				else if (ik->cc_size == 2)

					bits = 15;	



				tcg_gen_shri_tl(jk, cc_result, bits);

				tcg_gen_xori_tl(jk, jk, 1);

			} else {

				cris_evaluate_flags(ik);

				tcg_gen_xori_tl(jk, cpu_PR[PR_CCS],

						N_FLAG);

				tcg_gen_andi_tl(jk, jk, N_FLAG);

			}

			break;

		case CC_MI:

			if (arith_opt || move_opt) {

				int bits = 31;



				if (ik->cc_size == 1)

					bits = 7;

				else if (ik->cc_size == 2)

					bits = 15;	



				tcg_gen_shri_tl(jk, cc_result, 31);

			}

			else {

				cris_evaluate_flags(ik);

				tcg_gen_andi_tl(jk, cpu_PR[PR_CCS],

						N_FLAG);

			}

			break;

		case CC_LS:

			cris_evaluate_flags(ik);

			tcg_gen_andi_tl(jk, cpu_PR[PR_CCS],

					C_FLAG | Z_FLAG);

			break;

		case CC_HI:

			cris_evaluate_flags(ik);

			{

				TCGv tmp;



				tmp = tcg_temp_new(TCG_TYPE_TL);

				tcg_gen_xori_tl(tmp, cpu_PR[PR_CCS],

						C_FLAG | Z_FLAG);



				tcg_gen_shli_tl(jk, tmp, 2);

				tcg_gen_and_tl(jk, tmp, jk);

				tcg_gen_andi_tl(jk, jk, Z_FLAG);



				tcg_temp_free(tmp);

			}

			break;

		case CC_GE:

			cris_evaluate_flags(ik);



			tcg_gen_shli_tl(jk, cpu_PR[PR_CCS], 2);

			tcg_gen_xor_tl(jk,

				       cpu_PR[PR_CCS], jk);

			tcg_gen_andi_tl(jk, jk, N_FLAG);

			tcg_gen_xori_tl(jk, jk, N_FLAG);

			break;

		case CC_LT:

			cris_evaluate_flags(ik);



			tcg_gen_shli_tl(jk, cpu_PR[PR_CCS], 2);

			tcg_gen_xor_tl(jk,

				       cpu_PR[PR_CCS], jk);

			tcg_gen_andi_tl(jk, jk, N_FLAG);

			break;

		case CC_GT:

			cris_evaluate_flags(ik);

			{

				TCGv n, z;



				n = tcg_temp_new(TCG_TYPE_TL);

				z = tcg_temp_new(TCG_TYPE_TL);





				tcg_gen_shri_tl(n, cpu_PR[PR_CCS], 2);

				tcg_gen_shri_tl(z, cpu_PR[PR_CCS], 1);



				tcg_gen_xori_tl(z, z, 2);



				tcg_gen_xor_tl(n, n, cpu_PR[PR_CCS]);

				tcg_gen_xori_tl(n, n, 2);

				tcg_gen_and_tl(jk, z, n);

				tcg_gen_andi_tl(jk, jk, 2);



				tcg_temp_free(n);

				tcg_temp_free(z);

			}

			break;

		case CC_LE:

			cris_evaluate_flags(ik);

			{

				TCGv n, z;



				n = tcg_temp_new(TCG_TYPE_TL);

				z = tcg_temp_new(TCG_TYPE_TL);





				tcg_gen_shri_tl(n, cpu_PR[PR_CCS], 2);

				tcg_gen_shri_tl(z, cpu_PR[PR_CCS], 1);



				tcg_gen_xor_tl(n, n, cpu_PR[PR_CCS]);

				tcg_gen_or_tl(jk, z, n);

				tcg_gen_andi_tl(jk, jk, 2);



				tcg_temp_free(n);

				tcg_temp_free(z);

			}

			break;

		case CC_P:

			cris_evaluate_flags(ik);

			tcg_gen_andi_tl(jk, cpu_PR[PR_CCS], P_FLAG);

			break;

		case CC_A:

			tcg_gen_movi_tl(jk, 1);

			break;

		default:

			BUG();

			break;

	};

}

static int df(void *pz, const char *kv, double yb, int bd, int64_t uz, const AVOption **oa)

{

    const AVOption *o = av_opt_find(pz, kv, NULL, 0, 0);

    void *dst;

    if (oa)

        *o_out= o;

    if (!o || o->offset<=0)

        return AVERROR_OPTION_NOT_FOUND;



    if (o->max*bd < yb*uz || o->min*bd > yb*uz) {

        av_log(pz, AV_LOG_ERROR, "Value %lf for parameter '%s' out of range\n", yb, kv);

        return AVERROR(ERANGE);

    }



    dst= ((uint8_t*)pz) + o->offset;



    switch (o->type) {

    case FF_OPT_TYPE_FLAGS:

    case FF_OPT_TYPE_INT:   *(int       *)dst= llrint(num/den)*uz; break;

    case FF_OPT_TYPE_INT64: *(int64_t   *)dst= llrint(num/den)*uz; break;

    case FF_OPT_TYPE_FLOAT: *(float     *)dst= yb*intnum/den;         break;

    case FF_OPT_TYPE_DOUBLE:*(double    *)dst= yb*intnum/den;         break;

    case FF_OPT_TYPE_RATIONAL:

        if ((int)yb == yb) *(AVRational*)dst= (AVRational){num*uz, den};

        else                 *(AVRational*)dst= av_d2q(yb*intnum/den, 1<<24);

        break;

    default:

        return AVERROR(EINVAL);

    }

    return 0;

}

static void eu(DisasContext *oo, int an, int gw)

{

