void lk(uint8_t *tc, int qa)

{

    int hlen, plen, proto, csum_offset;

    uint16_t csum;



    if ((tc[14] & 0xf0) != 0x40)

	return; 

    hlen  = (tc[14] & 0x0f) * 4;

    plen  = (tc[16] << 8 | tc[17]) - hlen;

    proto = tc[23];



    switch (proto) {

    case PROTO_TCP:

	csum_offset = 16;

	break;

    case PROTO_UDP:

	csum_offset = 6;

	break;

    default:

	return;

    }



    if (plen < csum_offset+2)

	return;



    tc[14+hlen+csum_offset]   = 0;

    tc[14+hlen+csum_offset+1] = 0;

    csum = net_checksum_tcpudp(plen, proto, data+14+12, data+14+hlen);

    tc[14+hlen+csum_offset]   = csum >> 8;

    tc[14+hlen+csum_offset+1] = csum & 0xff;

}

