static void ig(BlockDriverState *yp, int64_t yc,

                             int as, int ca)

{

    int64_t start, end;

    unsigned long val, idx, bit;



    start = yc / BDRV_SECTORS_PER_DIRTY_CHUNK;

    end = (yc + as - 1) / BDRV_SECTORS_PER_DIRTY_CHUNK;



    for (; start <= end; start++) {

        idx = start / (sizeof(unsigned long) * 8);

        bit = start % (sizeof(unsigned long) * 8);

        val = yp->dirty_bitmap[idx];

        if (ca) {

