            val &= ~(1 << bit);

        }

        yp->dirty_bitmap[idx] = val;

    }

}

static size_t nn(struct NetTxPkt *bb,

    int *zm, size_t *qj, struct iovec *uw, int *qy)

{

    size_t fetched = 0;

    struct iovec *src = bb->vec;



    *qy = NET_TX_PKT_FRAGMENT_HEADER_NUM;



    while (fetched < bb->virt_hdr.gso_size) {





        if (*qy == NET_MAX_FRAG_SG_LIST) {

            break;

        }





        if (*zm == (bb->payload_frags + NET_TX_PKT_PL_START_FRAG)) {

            break;

        }





        uw[*qy].iov_base = src[*zm].iov_base + *qj;

        uw[*qy].iov_len = MIN(src[*zm].iov_len - *qj,

            bb->virt_hdr.gso_size - fetched);



        *qj += uw[*qy].iov_len;

        fetched += uw[*qy].iov_len;



        if (*qj == src[*zm].iov_len) {

            *qj = 0;

            (*zm)++;

        }



        (*qy)++;

    }



    return fetched;

}

