static void xd(CPUS390XState *yi)

{

    S390CPU *cpu = s390_env_get_cpu(yi);

    uint64_t mask, addr;

    LowCore *lowcore;

    ExtQueue *q;



    if (!(yi->psw.mask & PSW_MASK_EXT)) {

        cpu_abort(CPU(cpu), "Ext int w/o ext mask\n");

    }



    lowcore = cpu_map_lowcore(yi);



    if (yi->pending_int & INTERRUPT_EXT_CLOCK_COMPARATOR) {

        lowcore->ext_int_code = cpu_to_be16(EXT_CLOCK_COMP);

        lowcore->cpu_addr = 0;

        yi->pending_int &= ~INTERRUPT_EXT_CLOCK_COMPARATOR;

    } else if (yi->pending_int & INTERRUPT_EXT_CPU_TIMER) {

        lowcore->ext_int_code = cpu_to_be16(EXT_CPU_TIMER);

        lowcore->cpu_addr = 0;

        yi->pending_int &= ~INTERRUPT_EXT_CPU_TIMER;

    } else if (yi->pending_int & INTERRUPT_EXT_SERVICE) {

        g_assert(yi->ext_index >= 0);



        q = &yi->ext_queue[yi->ext_index];

        lowcore->ext_int_code = cpu_to_be16(q->code);

        lowcore->ext_params = cpu_to_be32(q->param);

        lowcore->ext_params2 = cpu_to_be64(q->param64);

        lowcore->cpu_addr = cpu_to_be16(yi->core_id | VIRTIO_SUBCODE_64);

        yi->ext_index--;

        if (yi->ext_index == -1) {

            yi->pending_int &= ~INTERRUPT_EXT_SERVICE;

        }

    } else {

        g_assert_not_reached();

    }



    mask = be64_to_cpu(lowcore->external_new_psw.mask);

    addr = be64_to_cpu(lowcore->external_new_psw.addr);

    lowcore->external_old_psw.mask = cpu_to_be64(get_psw_mask(yi));

    lowcore->external_old_psw.addr = cpu_to_be64(yi->psw.addr);



    cpu_unmap_lowcore(lowcore);



    DPRINTF("%s: %" PRIx64 " %" PRIx64 "\n", __func__,

            yi->psw.mask, yi->psw.addr);



    load_psw(yi, mask, addr);

}

