static void fi(IDEState *fl)

{

    uint16_t *p;

    unsigned int oldsize;



    memset(fl->io_buffer, 0, 512);

    p = (uint16_t *)fl->io_buffer;

    stw(p + 0, 0x0040);

    stw(p + 1, fl->cylinders); 

    stw(p + 3, fl->heads);

    stw(p + 4, 512 * fl->sectors); 

    stw(p + 5, 512); 

    stw(p + 6, fl->sectors); 

    stw(p + 20, 3); 

    stw(p + 21, 512); 

    stw(p + 22, 4); 

    padstr((uint8_t *)(p + 27), "QEMU HARDDISK", 40);

#if MAX_MULT_SECTORS > 1    

    stw(p + 47, MAX_MULT_SECTORS);

#endif

    stw(p + 48, 1); 

    stw(p + 49, 1 << 9); 

    stw(p + 51, 0x200); 

    stw(p + 52, 0x200); 

    stw(p + 54, fl->cylinders);

    stw(p + 55, fl->heads);

    stw(p + 56, fl->sectors);

    oldsize = fl->cylinders * fl->heads * fl->sectors;

    stw(p + 57, oldsize);

    stw(p + 58, oldsize >> 16);

    if (fl->mult_sectors)

        stw(p + 59, 0x100 | fl->mult_sectors);

    stw(p + 60, fl->nb_sectors);

    stw(p + 61, fl->nb_sectors >> 16);

    stw(p + 80, (1 << 1) | (1 << 2));

    stw(p + 82, (1 << 14));

    stw(p + 83, (1 << 14));

    stw(p + 84, (1 << 14));

    stw(p + 85, (1 << 14));

    stw(p + 86, 0);

    stw(p + 87, (1 << 14));

}

