static av_cold void ah(VLC *yg, uint16_t **xr,

                                  float **yz, uint16_t **he,

                                  const CoefVLCTable *an)

{

    int n                        = an->n;

    const uint8_t  *table_bits   = an->huffbits;

    const uint32_t *table_codes  = an->huffcodes;

    const uint16_t *levels_table = an->levels;

    uint16_t *run_table, *level_table, *int_table;

    float *flevel_table;

    int i, l, j, k, level;



    init_vlc(yg, VLCBITS, n, table_bits, 1, 1, table_codes, 4, 4, 0);



    run_table    = av_malloc(n * sizeof(uint16_t));

    level_table  = av_malloc(n * sizeof(uint16_t));

    flevel_table = av_malloc(n * sizeof(*flevel_table));

    int_table    = av_malloc(n * sizeof(uint16_t));

    i            = 2;

    level        = 1;

    k            = 0;

    while (i < n) {

        int_table[k] = i;

        l            = levels_table[k++];

        for (j = 0; j < l; j++) {

            run_table[i]    = j;

            level_table[i]  = level;

            flevel_table[i] = level;

            i++;

        }

        level++;

    }

    *xr   = run_table;

    *yz = flevel_table;

    *he   = int_table;

    av_free(level_table);

}

