static int coroutine_fn bn(BlockDriverState *cs,

                                          BlockDriverState *dq,

                                          int64_t eu,

                                          int mc, int *ss)

{

    BlockDriverState *intermediate;

    int ret, n;



    ret = bdrv_co_is_allocated(cs, eu, mc, &n);

    if (ret) {

        *ss = n;

        return ret;

    }





    intermediate = cs->backing_hd;



    while (intermediate != dq) {

        int pnum_inter;



        ret = bdrv_co_is_allocated(intermediate, eu, mc,

                                   &pnum_inter);

        if (ret < 0) {

            return ret;

        } else if (ret) {

            *ss = pnum_inter;

            return 0;

        }





        if (n > pnum_inter) {

            n = pnum_inter;

        }



        intermediate = intermediate->backing_hd;

    }



    *ss = n;

    return 1;

}

