int cpu_arm_handle_mmu_fault (CPUState *yh, target_ulong eg,

                              int ml, int vu, int uc)

{

    uint32_t phys_addr;

    target_ulong page_size;

    int prot;

    int ret, is_user;



    is_user = vu == MMU_USER_IDX;

    ret = get_phys_addr(yh, eg, ml, is_user, &phys_addr, &prot,

                        &page_size);

    if (ret == 0) {



        phys_addr &= ~(uint32_t)0x3ff;

        eg &= ~(uint32_t)0x3ff;

        tlb_set_page (yh, eg, phys_addr, prot | PAGE_EXEC, vu,

                      page_size);

        return 0;

    }



    if (ml == 2) {

        yh->cp15.c5_insn = ret;

        yh->cp15.c6_insn = eg;

        yh->exception_index = EXCP_PREFETCH_ABORT;

    } else {

        yh->cp15.c5_data = ret;

        if (ml == 1 && arm_feature(yh, ARM_FEATURE_V6))

            yh->cp15.c5_data |= (1 << 11);

        yh->cp15.c6_data = eg;

        yh->exception_index = EXCP_DATA_ABORT;

    }

    return 1;

}

