         bh = atomic_rcu_read(&bh->next)) {

        if (bh->scheduled) {

            if (bh->idle) {



                timeout = 10000000;

            } else {



                return 0;

            }

        }

    }



    deadline = timerlistgroup_deadline_ns(&pr->tlg);

