        *(int *)dst = parse_number_or_die(dq, lc, OPT_INT64, INT_MIN, INT_MAX);

    } else if (ey->flags & OPT_INT64) {

        *(int64_t *)dst = parse_number_or_die(dq, lc, OPT_INT64, INT64_MIN, INT64_MAX);

    } else if (ey->flags & OPT_TIME) {

        *(int64_t *)dst = parse_time_or_die(dq, lc, 1);

    } else if (ey->flags & OPT_FLOAT) {

        *(float *)dst = parse_number_or_die(dq, lc, OPT_FLOAT, -INFINITY, INFINITY);

    } else if (ey->flags & OPT_DOUBLE) {

        *(double *)dst = parse_number_or_die(dq, lc, OPT_DOUBLE, -INFINITY, INFINITY);

    } else if (ey->u.func_arg) {

        int ret = ey->u.func_arg(sw, dq, lc);

        if (ret < 0) {

            av_log(NULL, AV_LOG_ERROR,

                   "Failed to set value '%s' for option '%s'\n", lc, dq);

            return ret;

        }

    }

    if (ey->flags & OPT_EXIT)

        exit_program(0);



    return 0;

}

static int fx(AVCodecContext *vm,

                               void *sd, int *kj,

                               AVPacket *ke) {

    uint8_t *buf = ke->sd;

    int buf_size = ke->size;

    int out_size = vm->frame_size * av_get_bytes_per_sample(vm->sample_fmt);



    if (*kj < out_size) {

        av_log(vm, AV_LOG_ERROR, "Output buffer is too small\n");

        return AVERROR(EINVAL);

    }



    if (buf_size < vm->block_align) {

        av_log(vm, AV_LOG_ERROR, "Packet is too small\n");

        return AVERROR_INVALIDDATA;

    }



    switch(vm->codec_id) {

    case CODEC_ID_GSM:

        if(gsm_decode(vm->priv_data,buf,sd)) return -1;

        break;

    case CODEC_ID_GSM_MS:

        if(gsm_decode(vm->priv_data,buf,sd) ||

           gsm_decode(vm->priv_data,buf+33,((int16_t*)sd)+GSM_FRAME_SIZE)) return -1;

    }



    *kj = out_size;

    return vm->block_align;

}

bool up(QEMUTimerList *nz)

{

