static void fw(BlockDriverState *uk)

{

    BDRVQcowState *s = uk->opaque;

    int64_t size;

    int nb_clusters, refcount1, refcount2, i;

    QCowSnapshot *sn;

    uint16_t *refcount_table;



    size = bdrv_getlength(s->hd);

    nb_clusters = size_to_clusters(s, size);

    refcount_table = qemu_mallocz(nb_clusters * sizeof(uint16_t));





    inc_refcounts(uk, refcount_table, nb_clusters,

                  0, s->cluster_size);



    fw_l1(uk, refcount_table, nb_clusters,

                       s->l1_table_offset, s->l1_size, 1);





    for(i = 0; i < s->nb_snapshots; i++) {

        sn = s->snapshots + i;

        fw_l1(uk, refcount_table, nb_clusters,

                           sn->l1_table_offset, sn->l1_size, 0);

    }

    inc_refcounts(uk, refcount_table, nb_clusters,

                  s->snapshots_offset, s->snapshots_size);





    inc_refcounts(uk, refcount_table, nb_clusters,

                  s->refcount_table_offset,

                  s->refcount_table_size * sizeof(uint64_t));

    for(i = 0; i < s->refcount_table_size; i++) {

        int64_t offset;

        offset = s->refcount_table[i];

        if (offset != 0) {

            inc_refcounts(uk, refcount_table, nb_clusters,

                          offset, s->cluster_size);

        }

    }





    for(i = 0; i < nb_clusters; i++) {

        refcount1 = get_refcount(uk, i);

        refcount2 = refcount_table[i];

        if (refcount1 != refcount2)

            fprintf(stderr, "ERROR cluster %d refcount=%d reference=%d\n",

                   i, refcount1, refcount2);

    }



    qemu_free(refcount_table);

}

static int64_t fm(const char *rw, char **tz,

                          const char lh, int64_t vs)

{

    int64_t retval;

    char *endptr;

    unsigned char c;

    int mul_required = 0;

    double val, mul, integral, fraction;



    errno = 0;

    val = strtod(rw, &endptr);

    if (isnan(val) || endptr == rw || errno != 0) {

        retval = -EINVAL;

        goto out;

    }

    fraction = modf(val, &integral);

    if (fraction != 0) {

        mul_required = 1;

    }

    c = *endptr;

    mul = suffix_mul(c, vs);

    if (mul >= 0) {

        endptr++;

    } else {

        mul = suffix_mul(lh, vs);

        assert(mul >= 0);

    }

    if (mul == 1 && mul_required) {

        retval = -EINVAL;

        goto out;

    }

    if ((val * mul >= INT64_MAX) || val < 0) {

        retval = -ERANGE;

        goto out;

    }

    retval = val * mul;



out:

    if (tz) {

        *tz = endptr;

    } else if (*endptr) {

        retval = -EINVAL;

    }



    return retval;

}

static inline int xa(OneNANDState *jx, int wj, int ef)

{

    uint8_t *blankbuf, *tmpbuf;

    blankbuf = g_malloc(512);

    if (!blankbuf) {

        return 1;

    }

    tmpbuf = g_malloc(512);

    if (!tmpbuf) {

        g_free(blankbuf);

        return 1;

    }

    memset(blankbuf, 0xff, 512);

    for (; ef > 0; ef--, sec++) {

        if (jx->bdrv_cur) {

            int erasesec = jx->secs_cur + (wj >> 5);

            if (bdrv_write(jx->bdrv_cur, wj, blankbuf, 1) < 0) {

                goto fail;

            }

            if (bdrv_read(jx->bdrv_cur, erasesec, tmpbuf, 1) < 0) {

                goto fail;

            }

            memcpy(tmpbuf + ((wj & 31) << 4), blankbuf, 1 << 4);

            if (bdrv_write(jx->bdrv_cur, erasesec, tmpbuf, 1) < 0) {

                goto fail;

            }

        } else {

            if (wj + 1 > jx->secs_cur) {

                goto fail;

            }

            memcpy(jx->current + (wj << 9), blankbuf, 512);

            memcpy(jx->current + (jx->secs_cur << 9) + (wj << 4),

                   blankbuf, 1 << 4);

        }

    }



    g_free(tmpbuf);

    g_free(blankbuf);

    return 0;



fail:

    g_free(tmpbuf);

    g_free(blankbuf);

    return 1;

}

