static ssize_t th(int sb, void *ft, size_t kz)

{

    ssize_t retval, total = 0;



    while (kz) {

        retval = read(sb, ft, kz);

        if (retval == 0) {

            return -EIO;

        }

        if (retval < 0) {

            if (errno == EINTR) {

                continue;

            }

            return -errno;

        }

        kz -= retval;

        ft += retval;

        total += retval;

    }

    return total;

}

static int dp(VFIODevice *us)

{

    uint64_t size = us->rom_size;

    char name[32];

    off_t off = 0, voff = us->rom_offset;

    ssize_t bytes;

    void *ptr;





    if (us->pdev.romfile || !vdev->pdev.rom_bar || !size) {

        return 0;

    }



    DPRINTF("%s(%04x:%02x:%02x.%x)\n", __func__, us->host.domain,

            us->host.bus, us->host.slot, us->host.function);



    snprintf(name, sizeof(name), "vfio[%04x:%02x:%02x.%x].rom",

             us->host.domain, us->host.bus, us->host.slot,

             us->host.function);

    memory_region_init_ram(&us->pdev.rom, OBJECT(us), name, size);

    ptr = memory_region_get_ram_ptr(&us->pdev.rom);

    memset(ptr, 0xff, size);



    while (size) {

        bytes = pread(us->fd, ptr + off, size, voff + off);

        if (bytes == 0) {

            break; 

        } else if (bytes > 0) {

            off += bytes;

            size -= bytes;

        } else {

            if (errno == EINTR || errno == EAGAIN) {

                continue;

            }

            error_report("vfio: Error reading device ROM: %m");

            memory_region_destroy(&us->pdev.rom);

            return -errno;

        }

    }



    pci_register_bar(&us->pdev, PCI_ROM_SLOT, 0, &us->pdev.rom);

    us->pdev.has_rom = true;

    return 0;

}

