static void zs(TCGContext *bm, TCGMemOp ox, TCGCond nf, TCGArg np,

                           TCGArg ml, bool rm, TCGLabel *dp)

{

    intptr_t offset;

    bool need_cmp;



    if (rm && ml == 0 && (nf == TCG_COND_EQ || nf == TCG_COND_NE)) {

        need_cmp = false;

    } else {

        need_cmp = true;

        tcg_out_cmp(bm, ox, np, ml, rm);

    }



    if (!l->has_value) {

        tcg_out_reloc(bm, bm->code_ptr, R_AARCH64_CONDBR19, dp, 0);

        offset = tcg_in32(bm) >> 5;

    } else {

        offset = dp->u.value_ptr - bm->code_ptr;

        assert(offset == sextract64(offset, 0, 19));

    }



    if (need_cmp) {

        tcg_out_insn(bm, 3202, B_C, nf, offset);

    } else if (nf == TCG_COND_EQ) {

        tcg_out_insn(bm, 3201, CBZ, ox, np, offset);

    } else {

        tcg_out_insn(bm, 3201, CBNZ, ox, np, offset);

    }

}

