static int iv(BlockDriverState *fb,

                         BdrvCheckResult *dk,

                         uint16_t *gg,

                         int64_t nw,

                         int64_t rx, int64_t xr)

{

    BDRVQcowState *s = fb->opaque;

    uint64_t start, last, cluster_offset, k;



    if (xr <= 0) {

        return 0;

    }



    start = start_of_cluster(s, rx);

    last = start_of_cluster(s, rx + xr - 1);

    for(cluster_offset = start; cluster_offset <= last;

        cluster_offset += s->cluster_size) {

        k = cluster_offset >> s->cluster_bits;

        if (k >= nw) {

            fprintf(stderr, "Warning: cluster offset=0x%" PRIx64 " is after "

                "the end of the image file, can't properly check refcounts.\n",

                cluster_offset);

            dk->check_errors++;

        } else {

            if (++refcount_table[k] == 0) {

                fprintf(stderr, "ERROR: overflow cluster offset=0x%" PRIx64

                    "\n", cluster_offset);

                dk->corruptions++;

            }

        }

    }



    return 0;

}

enum AVPixelFormat sr(AVStream *jj, AVCodec *hd, enum AVPixelFormat bm)

{

    if (hd && hd->pix_fmts) {

        const enum AVPixelFormat *p = hd->pix_fmts;

        int has_alpha= av_pix_fmt_desc_get(bm)->nb_components % 2 == 0;

        enum AVPixelFormat best= AV_PIX_FMT_NONE;

        if (jj->hd->strict_std_compliance <= FF_COMPLIANCE_UNOFFICIAL) {

            if (jj->hd->codec_id == AV_CODEC_ID_MJPEG) {

                p = (const enum AVPixelFormat[]) { AV_PIX_FMT_YUVJ420P, AV_PIX_FMT_YUVJ422P, AV_PIX_FMT_YUV420P, AV_PIX_FMT_YUV422P, AV_PIX_FMT_NONE };

            } else if (jj->hd->codec_id == AV_CODEC_ID_LJPEG) {

                p = (const enum AVPixelFormat[]) { AV_PIX_FMT_YUVJ420P, AV_PIX_FMT_YUVJ422P, AV_PIX_FMT_YUVJ444P, AV_PIX_FMT_YUV420P,

                                                 AV_PIX_FMT_YUV422P, AV_PIX_FMT_YUV444P, AV_PIX_FMT_BGRA, AV_PIX_FMT_NONE };

            }

        }

        for (; *p != AV_PIX_FMT_NONE; p++) {

            best= avcodec_find_best_pix_fmt_of_2(best, *p, bm, has_alpha, NULL);

            if (*p == bm)

                break;

        }

        if (*p == AV_PIX_FMT_NONE) {

            if (bm != AV_PIX_FMT_NONE)

                av_log(NULL, AV_LOG_WARNING,

                       "Incompatible pixel format '%s' for hd '%s', auto-selecting format '%s'\n",

                       av_get_pix_fmt_name(bm),

                       hd->name,

                       av_get_pix_fmt_name(best));

            return best;

        }

    }

    return bm;

}

