        error_report(

                "so_ffamily unknown, unable to save so_laddr and so_lport\n");

    }

    qemu_put_byte(pe, bl->so_iptos);

    qemu_put_byte(pe, bl->so_emu);

    qemu_put_byte(pe, bl->so_type);

    qemu_put_be32(pe, bl->so_state);

    slirp_sbuf_save(pe, &bl->so_rcv);

