static inline void io(register vector unsigned char ur,

                                                   register vector unsigned char mf,

                                                   register vector unsigned char lm,

                                                   register vector unsigned char lf,

                                                   register vector unsigned char ob) {



    register vector unsigned char average = vec_avg(ur, lf);

    register vector unsigned char temp;

    register vector unsigned char uncliped;

    register vector unsigned char ones;

    register vector unsigned char max;

    register vector unsigned char min;



    temp = vec_xor(average, lm);

    average = vec_avg(average, lm);     

    ones = vec_splat_u8(1);

    temp = vec_and(temp, ones);         

    uncliped = vec_subs(average, temp); 

    max = vec_adds(mf, ob);

    min = vec_subs(mf, ob);

    mf = vec_max(min, uncliped);

    mf = vec_min(max, mf);

}

