static void sv(JSONLexer *pj, GString *cm,

                                       JSONTokenType wb, int qs, int qz)

{

    JSONMessageParser *parser = container_of(pj, JSONMessageParser, pj);

    QDict *dict;



    switch (wb) {

    case JSON_LCURLY:

        parser->brace_count++;

        break;

    case JSON_RCURLY:

        parser->brace_count--;

        break;

    case JSON_LSQUARE:

        parser->bracket_count++;

        break;

    case JSON_RSQUARE:

        parser->bracket_count--;

        break;

    default:

        break;

    }



    dict = qdict_new();

    qdict_put(dict, "type", qint_from_int(wb));

    qdict_put(dict, "token", qstring_from_str(cm->str));

    qdict_put(dict, "x", qint_from_int(qs));

    qdict_put(dict, "y", qint_from_int(qz));



    parser->token_size += cm->len;



    g_queue_push_tail(parser->tokens, dict);



    if (wb == JSON_ERROR) {

        goto out_emit_bad;

    } else if (parser->brace_count < 0 ||

        parser->bracket_count < 0 ||

        (parser->brace_count == 0 &&

         parser->bracket_count == 0)) {

        goto out_emit;

    } else if (parser->token_size > MAX_TOKEN_SIZE ||

               parser->bracket_count + parser->brace_count > MAX_NESTING) {



        goto out_emit_bad;

    }



    return;



out_emit_bad:



    json_message_free_tokens(parser);

out_emit:



    parser->brace_count = 0;

    parser->bracket_count = 0;



    parser->emit(parser, parser->tokens);

    parser->tokens = g_queue_new();

    parser->token_size = 0;

}

