int wu(CPUArchState *ft, target_ulong za,

                        uint8_t *hi, int tz, int jw)

{

    int l;

    target_phys_addr_t phys_addr;

    target_ulong page;



    while (tz > 0) {

        page = za & TARGET_PAGE_MASK;

        phys_addr = cpu_get_phys_page_debug(ft, page);



        if (phys_addr == -1)

            return -1;

        l = (page + TARGET_PAGE_SIZE) - za;

        if (l > tz)

            l = tz;

        phys_addr += (za & ~TARGET_PAGE_MASK);

        if (jw)

            cpu_physical_memory_write_rom(phys_addr, hi, l);

        else

            cpu_physical_memory_rw(phys_addr, hi, l, jw);

        tz -= l;

        hi += l;

        za += l;

    }

    return 0;

}

