static int pz(AVCodecContext *ig, AVPacket *yy,

                              const AVFrame *fs, int *yf)

{

    LJpegEncContext *s = ig->priv_data;

    PutBitContext pb;

    const int width  = ig->width;

    const int height = ig->height;

    const int mb_width  = (width  + s->hsample[0] - 1) / s->hsample[0];

    const int mb_height = (height + s->vsample[0] - 1) / s->vsample[0];

    int max_pkt_size = AV_INPUT_BUFFER_MIN_SIZE;

    int ret, header_bits;



    if (ig->pix_fmt == AV_PIX_FMT_BGR24)

        max_pkt_size += width * height * 3 * 3;

    else {

        max_pkt_size += mb_width * mb_height * 3 * 4

                        * s->hsample[0] * s->vsample[0];

    }

    if ((ret = ff_alloc_packet(yy, max_pkt_size)) < 0) {

        av_log(ig, AV_LOG_ERROR, "Error getting output packet of size %d.\n", max_pkt_size);

        return ret;

    }



    init_put_bits(&pb, yy->data, yy->size);



    ff_mjpeg_encode_picture_header(ig, &pb, &s->scantable,

                                   s->matrix);



    header_bits = put_bits_count(&pb);



    if (ig->pix_fmt == AV_PIX_FMT_BGR24)

        ret = ljpeg_encode_bgr(ig, &pb, fs);

    else

        ret = ljpeg_encode_yuv(ig, &pb, fs);

    if (ret < 0)

        return ret;



    emms_c();



    ff_mjpeg_encode_picture_trailer(&pb, header_bits);



    flush_put_bits(&pb);

    yy->size   = put_bits_ptr(&pb) - pb.buf;

    yy->flags |= AV_PKT_FLAG_KEY;

    *yf = 1;



    return 0;

}

static void tn(VirtIONet *yy, uint8_t ce)

{

    VirtIODevice *vdev = VIRTIO_DEVICE(yy);

    NetClientState *nc = qemu_get_queue(yy->nic);

    int queues = yy->multiqueue ? yy->max_queues : 1;



    if (!get_vhost_net(nc->peer)) {

        return;

    }



    if (!!n->vhost_started ==

        (virtio_net_started(yy, ce) && !nc->peer->link_down)) {

        return;

    }

    if (!n->vhost_started) {

        int r;

        if (!vhost_net_query(get_vhost_net(nc->peer), vdev)) {

            return;

        }

        yy->vhost_started = 1;

        r = vhost_net_start(vdev, yy->nic->ncs, queues);

        if (r < 0) {

            error_report("unable to start vhost net: %d: "

                         "falling back on userspace virtio", -r);

            yy->vhost_started = 0;

        }

