int ga(AcpiPciHpState *xl, PCIDevice *ak,

                              PCIHotplugState yq)

{

    int slot = PCI_SLOT(ak->devfn);

    int bsel = acpi_pcihp_get_bsel(ak->bus);

    if (bsel < 0) {

        return -1;

    }





    if (yq == PCI_COLDPLUG_ENABLED) {

        xl->acpi_pcihp_pci_status[bsel].device_present |= (1U << slot);

