static void cb(H264Context *hh, int map[2][16+32], int je, int dm, int qs, int jf){

    MpegEncContext * const s = &hh->s;

    Picture * const ref1 = &hh->ref_list[1][0];

    int j, old_ref, rfield;

    int start= jf ? 16                      : 0;

    int end  = jf ? 16+2*hh->ref_count[0]    : hh->ref_count[0];

    int interl= jf || s->picture_structure != PICT_FRAME;





    memset(map[je], 0, sizeof(map[je]));



    for(rfield=0; rfield<2; rfield++){

        for(old_ref=0; old_ref<ref1->ref_count[qs][je]; old_ref++){

            int poc = ref1->ref_poc[qs][je][old_ref];



            if     (!interl)

                poc |= 3;

            else if( interl && (poc&3) == 3) 

                poc= (poc&~3) + rfield + 1;



            for(j=start; j<end; j++){

                if (4 * hh->ref_list[0][j].frame_num + (hh->ref_list[0][j].f.reference & 3) == poc) {

                    int cur_ref= jf ? (j-16)^field : j;

                    map[je][2*old_ref + (rfield^field) + 16] = cur_ref;

                    if(rfield == dm || !interl)

                        map[je][old_ref] = cur_ref;

                    break;

                }

            }

        }

    }

}

static void pl(int *jj, int *ox,

                                   AVFormatContext *qt, AVStream *qk, 

                                   AVCodecParserContext *nv, AVPacket *ek)

{

    int frame_size;



    *jj = 0;

    *ox = 0;

    switch(qk->codec.codec_type) {

    case CODEC_TYPE_VIDEO:

        *jj = qk->codec.frame_rate_base;

        *ox = qk->codec.frame_rate;

        if (nv && nv->repeat_pict) {

            *ox *= 2;

            *jj = (*jj) * (2 + nv->repeat_pict);

        }

        break;

    case CODEC_TYPE_AUDIO:

        frame_size = get_audio_frame_size(&qk->codec, ek->size);

        if (frame_size < 0)

