static int ab(int bt, uint8_t *bv, int64_t du)

{

    VHDDynDiskHeader *dyndisk_header =

        (VHDDynDiskHeader *) bv;

    size_t block_size, num_bat_entries;

    int i;

    int ret = -EIO;





    block_size = 0x200000;

    num_bat_entries = (du + block_size / 512) / (block_size / 512);



    if (write(bt, bv, HEADER_SIZE) != HEADER_SIZE) {

        goto fail;

    }



    if (lseek(bt, 1536 + ((num_bat_entries * 4 + 511) & ~511), SEEK_SET) < 0) {

        goto fail;

    }

    if (write(bt, bv, HEADER_SIZE) != HEADER_SIZE) {

        goto fail;

    }





    if (lseek(bt, 3 * 512, SEEK_SET) < 0) {

        goto fail;

    }



    memset(bv, 0xFF, 512);

    for (i = 0; i < (num_bat_entries * 4 + 511) / 512; i++) {

        if (write(bt, bv, 512) != 512) {

            goto fail;

        }

    }





    memset(bv, 0, 1024);



    memcpy(dyndisk_header->magic, "cxsparse", 8);





    dyndisk_header->data_offset = be64_to_cpu(0xFFFFFFFFFFFFFFFFULL);

    dyndisk_header->table_offset = be64_to_cpu(3 * 512);

    dyndisk_header->version = be32_to_cpu(0x00010000);

    dyndisk_header->block_size = be32_to_cpu(block_size);

    dyndisk_header->max_table_entries = be32_to_cpu(num_bat_entries);



    dyndisk_header->checksum = be32_to_cpu(vpc_checksum(bv, 1024));





    if (lseek(bt, 512, SEEK_SET) < 0) {

        goto fail;

    }



    if (write(bt, bv, 1024) != 1024) {

        goto fail;

    }

    ret = 0;



 fail:

    return ret;

}

static int md(BlockDriverState *wd,

                              QEMUSnapshotInfo **no)

{

    BDRVRBDState *s = wd->opaque;

    QEMUSnapshotInfo *sn_info, *sn_tab = NULL;

    int i, snap_count;

    rbd_snap_info_t *snaps;

    int max_snaps = RBD_MAX_SNAPS;



    do {

        snaps = g_malloc(sizeof(*snaps) * max_snaps);

        snap_count = rbd_snap_list(s->image, snaps, &max_snaps);

        if (snap_count < 0) {

            g_free(snaps);

        }

    } while (snap_count == -ERANGE);



    if (snap_count <= 0) {

        return snap_count;

    }



    sn_tab = g_malloc0(snap_count * sizeof(QEMUSnapshotInfo));



    for (i = 0; i < snap_count; i++) {

        const char *snap_name = snaps[i].name;



        sn_info = sn_tab + i;

        pstrcpy(sn_info->id_str, sizeof(sn_info->id_str), snap_name);

        pstrcpy(sn_info->name, sizeof(sn_info->name), snap_name);



        sn_info->vm_state_size = snaps[i].size;

        sn_info->date_sec = 0;

        sn_info->date_nsec = 0;

        sn_info->vm_clock_nsec = 0;

    }

    rbd_snap_list_end(snaps);



    *no = sn_tab;

    return snap_count;

}

