static int vp(OutputStream *aa, const uint8_t *vc, int ds)

{

    if (ds < 13)

        return AVERROR_INVALIDDATA;

    if (memcmp(vc, "FLV", 3))

        return AVERROR_INVALIDDATA;

    vc      += 13;

    ds -= 13;

    while (ds >= 11 + 4) {

        int type = vc[0];

        int size = AV_RB24(&vc[1]) + 11 + 4;

        if (size > ds)

            return AVERROR_INVALIDDATA;

        if (type == 8 || type == 9) {

            if (aa->nb_extra_packets > FF_ARRAY_ELEMS(aa->extra_packets))

                return AVERROR_INVALIDDATA;

            aa->extra_packet_sizes[aa->nb_extra_packets] = size;

            aa->extra_packets[aa->nb_extra_packets] = av_malloc(size);

            if (!os->extra_packets[aa->nb_extra_packets])

                return AVERROR(ENOMEM);

            memcpy(aa->extra_packets[aa->nb_extra_packets], vc, size);

            aa->nb_extra_packets++;

        } else if (type == 0x12) {

            if (aa->metadata)

                return AVERROR_INVALIDDATA;

            aa->metadata_size = size - 11 - 4;

            aa->metadata      = av_malloc(aa->metadata_size);

            if (!os->metadata)

                return AVERROR(ENOMEM);

            memcpy(aa->metadata, vc + 11, aa->metadata_size);

        }

        vc      += size;

        ds -= size;

    }

    if (!os->metadata)

        return AVERROR_INVALIDDATA;

    return 0;

}

static void yq(SDHCIState *ec)

{

    int index = 0;



    if (ec->prnsts & SDHC_SPACE_AVAILABLE) {

        if (ec->norintstsen & SDHC_NISEN_WBUFRDY) {

            ec->norintsts |= SDHC_NIS_WBUFRDY;

        }

        sdhci_update_irq(ec);

        return;

    }



    if (ec->trnmod & SDHC_TRNS_BLK_CNT_EN) {

        if (ec->blkcnt == 0) {

            return;

        } else {

            ec->blkcnt--;

        }

    }



    for (index = 0; index < (ec->blksize & 0x0fff); index++) {

        sd_write_data(ec->card, ec->fifo_buffer[index]);

    }





    ec->prnsts |= SDHC_SPACE_AVAILABLE;





    if ((ec->trnmod & SDHC_TRNS_MULTI) == 0 ||

            ((ec->trnmod & SDHC_TRNS_MULTI) &&

            (ec->trnmod & SDHC_TRNS_BLK_CNT_EN) && (ec->blkcnt == 0))) {

        SDHCI_GET_CLASS(ec)->end_data_transfer(ec);

    } else if (ec->norintstsen & SDHC_NISEN_WBUFRDY) {

        ec->norintsts |= SDHC_NIS_WBUFRDY;

    }





    if (ec->stopped_state == sdhc_gap_write && (ec->trnmod & SDHC_TRNS_MULTI) &&

            ec->blkcnt > 0) {

        ec->prnsts &= ~SDHC_DOING_WRITE;

        if (ec->norintstsen & SDHC_EISEN_BLKGAP) {

            ec->norintsts |= SDHC_EIS_BLKGAP;

        }

        SDHCI_GET_CLASS(ec)->end_data_transfer(ec);

    }



    sdhci_update_irq(ec);

}

