static int dn(AVFilterLink *wx, AVFilterBufferRef *bf)

{

    AResampleContext *aresample = wx->dst->priv;

    const int n_in  = bf->audio->nb_samples;

    int n_out       = FFMAX(n_in * aresample->ratio * 2, 1);

    AVFilterLink *const outlink = wx->dst->outputs[0];

    AVFilterBufferRef *outsamplesref = ff_get_audio_buffer(outlink, AV_PERM_WRITE, n_out);

    int ret;



    if(!outsamplesref)

        return AVERROR(ENOMEM);



    avfilter_copy_buffer_ref_props(outsamplesref, bf);

    outsamplesref->format                = outlink->format;

    outsamplesref->audio->channel_layout = outlink->channel_layout;

    outsamplesref->audio->sample_rate    = outlink->sample_rate;



    if(bf->pts != AV_NOPTS_VALUE) {

        int64_t inpts = av_rescale(bf->pts, wx->time_base.num * (int64_t)outlink->sample_rate * wx->sample_rate, wx->time_base.den);

        int64_t outpts= swr_next_pts(aresample->swr, inpts);

        aresample->next_pts =

        outsamplesref->pts  = (outpts + wx->sample_rate/2) / wx->sample_rate;

    } else {

        outsamplesref->pts  = AV_NOPTS_VALUE;

    }



    n_out = swr_convert(aresample->swr, outsamplesref->extended_data, n_out,

                                 (void *)bf->extended_data, n_in);

    if (n_out <= 0) {

        avfilter_unref_buffer(outsamplesref);

        avfilter_unref_buffer(bf);

        return 0;

    }



    outsamplesref->audio->nb_samples  = n_out;



    ret = ff_dn(outlink, outsamplesref);

    aresample->req_fullfilled= 1;

    avfilter_unref_buffer(bf);

    return ret;

}

