void fc(CPUMIPSState *fq, target_ulong pp)

{

    target_ulong old, val, mask;

    mask = (TARGET_PAGE_MASK << 1) | fq->CP0_EntryHi_ASID_mask;

    if (((fq->CP0_Config4 >> CP0C4_IE) & 0x3) >= 2) {

        mask |= 1 << CP0EnHi_EHINV;

    }





#if defined(TARGET_MIPS64)

    if (fq->insn_flags & ISA_MIPS32R6) {

        int entryhi_r = extract64(pp, 62, 2);

        int config0_at = extract32(fq->CP0_Config0, 13, 2);

        bool no_supervisor = (fq->CP0_Status_rw_bitmask & 0x8) == 0;

        if ((entryhi_r == 2) ||

            (entryhi_r == 1 && (no_supervisor || config0_at == 1))) {



            mask &= ~(0x3ull << 62);

        }

    }

    mask &= fq->SEGMask;

#endif

    old = fq->CP0_EntryHi;

    val = (pp & mask) | (old & ~mask);

    fq->CP0_EntryHi = val;

    if (fq->CP0_Config3 & (1 << CP0C3_MT)) {

        sync_c0_entryhi(fq, fq->current_tc);

    }



    if ((old & fq->CP0_EntryHi_ASID_mask) !=

        (val & fq->CP0_EntryHi_ASID_mask)) {

        cpu_mips_tlb_flush(fq);

    }

}

