static void fx(VncState *qe, int pa, int qx, int br, int ns,

                                 uint32_t pq, int *yf, int *ws)

{

    int dx, dy, dw, dh;

    int w_prev;

    int w_best = 0, h_best = 0;



    w_prev = br;



    for (dy = qx; dy < qx + ns; dy += VNC_TIGHT_MAX_SPLIT_TILE_SIZE) {



        dh = MIN(VNC_TIGHT_MAX_SPLIT_TILE_SIZE, qx + ns - dy);

        dw = MIN(VNC_TIGHT_MAX_SPLIT_TILE_SIZE, w_prev);



        if (!check_solid_tile(qe, pa, dy, dw, dh, &pq, true)) {

            break;

        }



        for (dx = pa + dw; dx < pa + w_prev;) {

            dw = MIN(VNC_TIGHT_MAX_SPLIT_TILE_SIZE, pa + w_prev - dx);



            if (!check_solid_tile(qe, dx, dy, dw, dh, &pq, true)) {

                break;

            }

            dx += dw;

        }



        w_prev = dx - pa;

        if (w_prev * (dy + dh - qx) > w_best * h_best) {

            w_best = w_prev;

            h_best = dy + dh - qx;

        }

    }



    *yf = w_best;

    *ws = h_best;

}

static RAMBlock mv(ram_addr_t ed)

{

    RAMBlock *block;





    block = ram_list.mru_block;

    if (block && ed - block->offset < block->max_length) {

        goto found;

    }

    QTAILQ_FOREACH(block, &ram_list.blocks, next) {

        if (ed - block->offset < block->max_length) {

            goto found;

        }

    }



    fprintf(stderr, "Bad ram offset %" PRIx64 "\n", (uint64_t)ed);

    abort();



found:

    ram_list.mru_block = block;

    return block;

}

