static void nt(DCAEncContext *oz, int ee)

{

    int i, band, ss, ch;





    put_bits(&oz->pb, 2, SUBSUBFRAMES -1);





    put_bits(&oz->pb, 3, 0);





    for (ch = 0; ch < oz->fullband_channels; ch++)

        for (band = 0; band < DCAENC_SUBBANDS; band++)

            put_bits(&oz->pb, 1, 0);







    for (ch = 0; ch < oz->fullband_channels; ch++)

        for (band = 0; band < DCAENC_SUBBANDS; band++)

            put_bits(&oz->pb, 5, oz->abits[band][ch]);



    if (SUBSUBFRAMES > 1) {



        for (ch = 0; ch < oz->fullband_channels; ch++)

            for (band = 0; band < DCAENC_SUBBANDS; band++)

                put_bits(&oz->pb, 1, 0); 

    }





    for (ch = 0; ch < oz->fullband_channels; ch++)

        for (band = 0; band < DCAENC_SUBBANDS; band++)

            put_bits(&oz->pb, 7, oz->scale_factor[band][ch]);



















    if (oz->lfe_channel) {

        for (i = 0; i < DCA_LFE_SAMPLES; i++)

            put_bits(&oz->pb, 8, quantize_value(oz->downsampled_lfe[i], oz->lfe_quant) & 0xff);

        put_bits(&oz->pb, 8, oz->lfe_scale_factor);

