static void sv(CPUMIPSState *dy, DisasContext *lr, uint32_t ps)

{

    uint8_t df = (lr->opcode >> 21) & 0x3;

    uint8_t wt = (lr->opcode >> 16) & 0x1f;

    int64_t s16 = (int16_t)lr->opcode;



    check_msa_access(lr);



    if (lr->insn_flags & ISA_MIPS32R6 && lr->hflags & MIPS_HFLAG_BMASK) {

        generate_exception_end(lr, EXCP_RI);

        return;

    }

    switch (ps) {

    case OPC_BZ_V:

    case OPC_BNZ_V:

        {

            TCGv_i64 t0 = tcg_temp_new_i64();

            tcg_gen_or_i64(t0, msa_wr_d[wt<<1], msa_wr_d[(wt<<1)+1]);

            tcg_gen_setcondi_i64((ps == OPC_BZ_V) ?

                    TCG_COND_EQ : TCG_COND_NE, t0, t0, 0);

            tcg_gen_trunc_i64_tl(bcond, t0);

            tcg_temp_free_i64(t0);

        }

        break;

    case OPC_BZ_B:

    case OPC_BZ_H:

    case OPC_BZ_W:

    case OPC_BZ_D:

        gen_check_zero_element(bcond, df, wt);

        break;

    case OPC_BNZ_B:

    case OPC_BNZ_H:

    case OPC_BNZ_W:

    case OPC_BNZ_D:

        gen_check_zero_element(bcond, df, wt);

        tcg_gen_setcondi_tl(TCG_COND_EQ, bcond, bcond, 0);

        break;

    }



    lr->btarget = lr->pc + (s16 << 2) + 4;



    lr->hflags |= MIPS_HFLAG_BC;

    lr->hflags |= MIPS_HFLAG_BDS32;

}

static QObject rj(JSONParserContext *wn, QList **vx)

{

    QObject *token, *ret;

    QList *working = qlist_copy(*vx);



    token = qlist_pop(working);

    if (token == NULL) {

        goto out;

    }



    if (token_get_type(token) != JSON_KEYWORD) {

        goto out;

    }



    if (token_is_keyword(token, "true")) {

        ret = QOBJECT(qbool_from_int(true));

    } else if (token_is_keyword(token, "false")) {

        ret = QOBJECT(qbool_from_int(false));

    } else {

        parse_error(wn, token, "invalid keyword `%s'", token_get_value(token));

        goto out;

    }



    qobject_decref(token);

    QDECREF(*vx);

    *vx = working;



    return ret;



out: 

    qobject_decref(token);

    QDECREF(working);



    return NULL;

}

