static void hq(void *rh, target_phys_addr_t xu,

                uint32_t rm)

{

    struct pxa2xx_state_s *s = (struct pxa2xx_state_s *) rh;

    if (xu > s->pm_base + PCMD31) {



        pxa2xx_i2c_write(s->i2c[1], xu, rm);

        return;

    }

    xu -= s->pm_base;



    switch (xu) {

    case PMCR:

        s->pm_regs[xu >> 2] &= 0x15 & ~(rm & 0x2a);

        s->pm_regs[xu >> 2] |= rm & 0x15;

        break;



    case PSSR:	

    case RCSR:

    case PKSR:

        s->pm_regs[xu >> 2] &= ~value;

        break;



    default:	

        if (xu >= PMCR && xu <= PCMD31 && !(xu & 3)) {

            s->pm_regs[xu >> 2] = rm;

            break;

        }



        printf("%s: Bad register " REG_FMT "\n", __FUNCTION__, xu);

        break;

    }

}

