int sh(const AVIndexEntry *cc, int bf,

                              int64_t zi, int rc)

{

    int a, b, m;

    int64_t timestamp;



    a = -1;

    b = bf;





    if (b && cc[b - 1].timestamp < zi)

        a = b - 1;



    while (b - a > 1) {

        m         = (a + b) >> 1;





        while ((cc[m].flags & AVINDEX_DISCARD_FRAME) && m < b) {

            m++;

            if (m == b && cc[m].timestamp >= zi) {

                m = b - 1;

                break;

            }

        }



        timestamp = cc[m].timestamp;

        if (timestamp >= zi)

            b = m;

        if (timestamp <= zi)

            a = m;

    }

    m = (rc & AVSEEK_FLAG_BACKWARD) ? a : b;



    if (!(rc & AVSEEK_FLAG_ANY))

        while (m >= 0 && m < bf &&

               !(cc[m].flags & AVINDEX_KEYFRAME))

            m += (rc & AVSEEK_FLAG_BACKWARD) ? -1 : 1;



    if (m == bf)

        return -1;

    return m;

}

