                       int na, int hb, int es)

{

    TCGv_i32 r_asi, r_size, r_sign;



    r_asi = gen_get_asi(pp, na);

    r_size = tcg_const_i32(hb);

    r_sign = tcg_const_i32(es);

#ifdef TARGET_SPARC64

    gen_helper_ld_asi(gs, cpu_env, fu, r_asi, r_size, r_sign);

#else

    {

        TCGv_i64 t64 = tcg_temp_new_i64();

        gen_helper_ld_asi(t64, cpu_env, fu, r_asi, r_size, r_sign);

        tcg_gen_trunc_i64_tl(gs, t64);

        tcg_temp_free_i64(t64);

    }

#endif

    tcg_temp_free_i32(r_sign);

    tcg_temp_free_i32(r_size);

    tcg_temp_free_i32(r_asi);

}

static inline float64 qb(uint64_t eu)

{

    union {

        uint64_t eu;

        float64 d;

    } v;



    v.i = eu;

    return v.d;

}

static void if(Visitor *se, void **bf)

{

    QmpInputVisitor *qiv = to_qiv(se);

    StackObject *tos = QSLIST_FIRST(&qiv->stack);



    assert(tos && tos->qapi == bf);

    QSLIST_REMOVE_HEAD(&qiv->stack, node);

    qmp_input_stack_object_free(tos);

}

av_cold void ts(H264Context *qm)

{

    int i;



    ff_h264_free_tables(qm);



    if (qm->DPB) {

        for (i = 0; i < H264_MAX_PICTURE_COUNT; i++)

            ff_h264_unref_picture(qm, &qm->DPB[i]);

        av_freep(&qm->DPB);

    }



    qm->cur_pic_ptr = NULL;



    for (i = 0; i < qm->nb_slice_ctx; i++)

        av_freep(&qm->slice_ctx[i].rbsp_buffer);

    av_freep(&qm->slice_ctx);

    qm->nb_slice_ctx = 0;



    for (i = 0; i < MAX_SPS_COUNT; i++)

        av_freep(qm->sps_buffers + i);



    for (i = 0; i < MAX_PPS_COUNT; i++)

        av_freep(qm->pps_buffers + i);

}
